const regions = [
{
name:'Северо-Восток', stamp:'СЕВЕРО-ВОСТОК 1925', subtitle:'Города, издательства, университеты, модернизм и кризис американской мечты', photos:[['Нью-Йорк и городская модерность','city'],['Издательства, журналы, литературный рынок','books'],['Театр, реклама, радио и массовая культура','media']], intro:'Северо-Восток в культуре США XX века можно рассматривать как регион городского модерна, интеллектуальной среды и медийной публичности. Нью-Йорк, Бостон, Филадельфия и другие центры стали пространством, где особенно заметно пересекались миграция, капитал, университеты, пресса, театр, реклама и новая массовая культура. Именно здесь американская мечта часто приобретала самый блестящий, но и самый противоречивый вид: она связывалась с карьерой, богатством, самосозданием личности, правом начать заново и одновременно с одиночеством, социальным неравенством и фальшью внешнего успеха.',
blocks:[
['1. Этническое и культурное многообразие','Северо-Восток формировался как один из главных центров иммиграционной Америки. В крупных городах региона встречались ирландские, итальянские, еврейские, немецкие, славянские и другие европейские общины, а также афроамериканское население, усилившееся в результате Великого переселения с Юга. Поэтому культурная идентичность региона строилась не на единой традиции, а на постоянном соседстве разных языков, религий, социальных привычек и городских укладов. Для литературы это важно: герой Северо-Востока часто существует в плотной, шумной, многонациональной среде, где человек одновременно получает больше возможностей и сильнее ощущает отчуждение.'],
['2. Технологии и массовая культура','Северо-Восток стал территорией газет, журналов, радио, рекламы, театральных афиш, издательств и городской потребительской культуры. Массовая культура здесь не просто развлекала, а формировала новый образ жизни: человек видел перед собой модели успеха, красоты, богатства, поведения и статуса. В литературе это проявляется через мотивы витринности и спектакля: персонажи будто играют социальные роли, создают себе биографии, подстраиваются под ожидания публики. Особенно ярко это видно у Фицджеральда, где блеск вечеринок и богатых районов скрывает духовную пустоту.'],
['3. Искусство и разные направления','Искусство Северо-Востока связано с модернизмом, городской прозой, театром, журнальной публицистикой, джазовой атмосферой 1920-х и психологической литературой середины века. Здесь развивалась культура эксперимента: менялись формы повествования, усиливался интерес к внутреннему миру героя, к языку, к фрагментарному восприятию реальности. Искусство региона отражало быстрый темп города: монтажность, диалогичность, резкую смену впечатлений, столкновение частной жизни и публичного пространства.'],
['4. Религия','Религиозная карта Северо-Востока была сложной. Протестантская этика труда и успеха соседствовала с католическими иммигрантскими общинами, иудейской интеллектуальной традицией и постепенно усиливающейся секуляризацией. В культуре это создавало напряжение между моральным долгом, личной свободой и прагматичным стремлением к успеху. У Сэлинджера эта линия переходит в духовный поиск и неприятие поверхностности, а у Фицджеральда религиозная мораль часто заменяется культом денег, статуса и желания быть признанным.'],
['5. Архитектура, скульптура, изобразительное искусство, литература, кинематограф, музыка','Архитектурный образ региона — небоскребы, мосты, вокзалы, университетские кампусы, театральные кварталы и богатые пригороды. Эта визуальная среда напрямую связана с литературой: город становится не фоном, а механизмом давления на героя. В «Великом Гэтсби» пространство Ист-Эгга, Вест-Эгга и Нью-Йорка превращается в карту классового разделения. В прозе Сэлинджера город дает герою свободу движения, но не дает внутреннего дома. Кинематограф и театр усиливали ощущение жизни как постановки, а джаз и популярная музыка задавали ритм эпохи.'],
['6. Философские учения периода','Для региона важны прагматизм, урбанистический индивидуализм, модернистское ощущение кризиса и послевоенный экзистенциальный вопрос о подлинности. Прагматическая культура учила оценивать идею по результату, но литература показывала ограниченность такого подхода: успех может быть достигнут, а смысл — потерян. Поэтому в произведениях авторов, связанных с Северо-Востоком, часто появляется конфликт между внешней эффективностью и внутренней правдой личности.'],
['7. Концепция американской мечты','На Северо-Востоке американская мечта особенно тесно связана с карьерой, деньгами, образованием, городским статусом и возможностью создать новую версию себя. Джей Гэтсби буквально конструирует собственную личность, чтобы приблизиться к мечте. Но регион показывает и кризис этого мифа: старые деньги остаются закрытым клубом, новые деньги не дают настоящего признания, а любовь и счастье не покупаются социальным успехом. Поэтому Северо-Восток — ключевая зона для анализа разрушения американской мечты.'],
['8. Влияние миграции и мультикультурализма','Миграция здесь видна не только как демографический процесс, но и как культурный двигатель. Иммигрантские кварталы, разные религиозные общины, языковая пестрота, социальная мобильность и попытка встроиться в американскую систему создавали особый тип городского героя. Он может быть амбициозным, образованным, талантливым, но часто вынужден доказывать свое право на принадлежность. Мультикультурализм региона раскрывает Америку как пространство возможностей и одновременно как пространство социальных фильтров.'],
['9. Глобализация и американизация','Северо-Восток был одним из центров, через которые американская культура становилась экспортируемой: издательства, пресса, театры, университеты и финансовые институты превращали культурные смыслы в национальные и международные. Нью-Йорк постепенно закреплялся как символ современной Америки: город скорости, капитала, медиа, рекламы, небоскребов и публичного успеха. Через литературу и массовую культуру этот образ стал узнаваемым далеко за пределами США.'],
['10. Влияние политических и социальных аспектов','Политически регион связан с вопросами иммиграции, классового разделения, городской бедности, элитного образования, медийной власти и послевоенного конформизма. Литература Северо-Востока часто вскрывает конфликт между публичным благополучием и личной неустроенностью. У Сэлинджера это конфликт подростка с миром взрослых, у Фицджеральда — конфликт мечты с классовой реальностью, у авторов послевоенной прозы — конфликт личности с обществом потребления.'],
['11. Авторы, особенности творчества','Ф. С. Фицджеральд показывает эпоху джаза, блеск богатства и трагедию мечты, которая оказывается недостижимой. Дж. Д. Сэлинджер создает голос подростка, не принимающего фальшь взрослого мира, и развивает тему духовного поиска. Аллен Гинзберг связан с Нью-Йорком как с ранней точкой битнической среды, но дальше его поэзия выходит в пространство контркультуры. Для региона характерны психологизм, городская чувствительность, интерес к языку публичности и критика внешнего успеха.']]
},
{
name:'Средний Запад', stamp:'СРЕДНИЙ ЗАПАД 1939', subtitle:'Труд, фермерская Америка, индустриальные города, прагматизм и социальная мобильность', photos:[['Фермерская Америка и малые города','farm'],['Заводы, железные дороги, индустриализация','factory'],['Пишущая машинка и код сдержанной прозы','typewriter']], intro:'Средний Запад раскрывает Америку труда, дисциплины, малых городов, фермерской этики, индустриальных центров и веры в практический результат. Это регион, где американская мечта чаще выглядит не как роскошная вечеринка, а как дом, работа, образование, уважение, семейная устойчивость и возможность подняться собственным усилием. Но именно здесь особенно заметно, что индивидуального труда не всегда достаточно: экономические кризисы, промышленная система, классовые барьеры и миграция меняют судьбу человека.',
blocks:[
['1. Этническое и культурное многообразие','Средний Запад часто воспринимается как «сердце» традиционной Америки, но его культурная реальность была многообразной. Здесь жили потомки европейских переселенцев, фермерские общины, рабочие индустриальных городов, афроамериканцы, прибывавшие в ходе Великого переселения, а также разные религиозные и этнические группы. Поэтому культурная идентичность региона строилась на сочетании сельской устойчивости и промышленного многообразия. В литературе это дает героя, который связан с землей, трудом и семьей, но одновременно сталкивается с модернизацией и социальной нестабильностью.'],
['2. Технологии и массовая культура','Технологии в Среднем Западе связаны прежде всего с промышленностью, транспортом, железными дорогами, сельскохозяйственной механизацией, заводским производством и ростом городов. Массовая культура проникала сюда через радио, газеты, кинотеатры, школьные и церковные сообщества, спортивные события и рекламу товаров для среднего класса. В отличие от Северо-Востока, где медиа связаны с блеском города, здесь массовая культура часто соединялась с повседневностью: семейным бытом, трудом, местным сообществом и представлением о нормальной жизни.'],
['3. Искусство и разные направления','Искусство Среднего Запада тяготеет к реализму, документальности, теме простого человека, трудовой этике и психологической сдержанности. В литературе важны точность детали, лаконизм, конфликт между мечтой и реальностью, внимание к моральному выбору. Здесь уместно говорить о социальном реализме, региональной прозе, послевоенной прозе о потерянности человека и о таком стиле, где внешняя простота скрывает внутреннюю драму.'],
['4. Религия','Религиозный код региона связан с протестантской этикой: трудолюбие, дисциплина, личная ответственность, умеренность, семейность, уважение к общине. Религия здесь часто работает не как внешняя символика, а как повседневный моральный каркас. Она задает представление о «правильной жизни»: трудиться, держать слово, помогать семье, не жаловаться, быть полезным. В литературе это может превращаться в конфликт: герой стремится соответствовать норме, но внутренне чувствует одиночество, усталость или невозможность быть счастливым в заданной системе.'],
['5. Архитектура, скульптура, изобразительное искусство, литература, кинематограф, музыка','Визуальный образ Среднего Запада — фермы, зернохранилища, церкви, школы, железные дороги, заводские кварталы, рабочие районы и широкие равнины. Архитектура здесь менее демонстративна, чем на Востоке или Западе, но она выражает практичность и устойчивость. В литературе это проявляется через пространство дороги, дома, фермы, завода, маленького города. Музыкально регион связан с кантри, блюзовыми и городскими рабочими влияниями, а кинематограф часто использует его как образ «обычной Америки», где проверяются базовые ценности.'],
['6. Философские учения периода','Средний Запад особенно хорошо связан с прагматизмом как американским способом мышления. Важны не абстрактные идеи, а то, как они работают в жизни: в образовании, труде, демократии, социальной организации. Через этот регион можно объяснять мысль Джона Дьюи о связи образования и демократии: человек должен не просто знать, а действовать, участвовать, развиваться. Но литература показывает и ограниченность прагматического оптимизма: практический успех не всегда спасает от одиночества и духовного кризиса.'],
['7. Концепция американской мечты','Американская мечта Среднего Запада — это мечта о достойной жизни через труд. Она менее гламурная, чем у Гэтсби, но не менее сильная: получить образование, купить дом, содержать семью, быть уважаемым, стать самостоятельным. Однако Великая депрессия, безработица, миграция и индустриальные кризисы показывают, что мечта зависит от экономической системы. Поэтому регион помогает увидеть социальную сторону американской мечты: успех не всегда определяется только волей человека.'],
['8. Влияние миграции и мультикультурализма','Миграция в Среднем Западе связана с движением рабочих в промышленные города, переселением афроамериканцев с Юга, перемещением фермерских семей во время экономических кризисов и внутренней мобильностью населения. Мультикультурализм здесь менее зрелищный, чем в Нью-Йорке или Калифорнии, но очень важный: он проявляется в соседстве этнических районов, рабочих сообществ, религиозных общин и разных моделей семейной жизни.'],
['9. Глобализация и американизация','Средний Запад стал одним из источников образа «обычной Америки», который активно распространялся через кино, телевидение, рекламу и массовую культуру. Образ фермы, малого города, честного работника, школьной команды, семейного дома и промышленного труда стал частью американского культурного экспорта. При этом глобализация постепенно меняла регион: промышленность перестраивалась, рабочие места исчезали или перемещались, а локальная идентичность вступала в конфликт с глобальной экономикой.'],
['10. Влияние политических и социальных аспектов','Регион связан с рабочим вопросом, промышленным развитием, профсоюзами, экономическими кризисами, сельским хозяйством, образовательной политикой и социальным неравенством. В культуре это проявляется через уважение к труду и одновременно тревогу перед потерей устойчивости. Литература показывает, что человек не существует отдельно от экономики: завод, ферма, банк, школа, дорога и рынок труда напрямую формируют его судьбу.'],
['11. Авторы, особенности творчества','Эрнест Хемингуэй связан со Средним Западом через происхождение, лаконичный стиль, дисциплину фразы и образ героя, который сохраняет достоинство в кризисе. Его проза строится на сдержанности: важное часто остается невысказанным. Джон Стейнбек географически сильнее связан с Западом, но его социальная проблематика помогает раскрыть миграцию, труд и экономическую уязвимость, важные и для Среднего Запада. Для региона характерны реализм, сдержанность, трудовая этика и интерес к человеку в системе социальных испытаний.']]
},
{
name:'Юг', stamp:'ЮГ 1936', subtitle:'Историческая память, расовый конфликт, религия, блюз, госпел и литература травмы', photos:[['Память Юга и старые дома','southpic'],['Блюз, госпел и афроамериканская музыка','blues'],['Движение за гражданские права','rights']], intro:'Юг — самый конфликтный и травматичный регион в культурной карте США XX века. Его идентичность строится на памяти о Гражданской войне, наследии рабства, расовой сегрегации, религиозности, сельской культуре, афроамериканской музыкальной традиции и борьбе за гражданские права. В литературе Юг почти всегда связан с прошлым, которое не исчезает: оно возвращается через семейные истории, расовую вину, насилие, молчание, мифы о «старом Юге» и попытку восстановить голоса тех, кого долго исключали из официальной культуры.',
blocks:[
['1. Этническое и культурное многообразие','Юг нельзя понимать только через образ белой плантаторской культуры. Его культурный код формировали афроамериканские общины, потомки европейских переселенцев, креольские традиции, коренные народы, религиозные общины, сельские и городские культуры. Но многообразие Юга было не равноправным: оно долго существовало в условиях расовой иерархии, сегрегации и насилия. Поэтому культурная идентичность региона включает не только смешение традиций, но и борьбу за право быть услышанным.'],
['2. Технологии и массовая культура','Технологии и массовая культура на Юге развивались в противоречии между традиционным укладом и модернизацией. Радио, грамзапись, телевидение и кино помогли вывести южную музыку и южные сюжеты на национальный уровень. Блюз, госпел, кантри и ранние формы джаза стали частью массовой культуры США. При этом медиа часто упрощали образ Юга, превращая его либо в романтизированный «старый мир», либо в пространство отсталости. Литература сопротивлялась этим схемам, показывая сложность региона.'],
['3. Искусство и разные направления','Искусство Юга связано с южным модернизмом, афроамериканской литературой, устной традицией, блюзовой поэтикой, религиозной образностью и историческим романом. Важная черта — память как художественный материал. Авторы работают с фрагментарным временем, семейными легендами, голосами прошлого, травмой рабства, расовым насилием и чувством вины. Южная литература часто не движется линейно вперед, а возвращается к неразрешенному прошлому.'],
['4. Религия','Религия на Юге — один из главных элементов культурной идентичности. Протестантские церкви, проповедь, библейский язык, госпел и общинная вера формировали моральный словарь региона. Но религия была двойственной: она могла оправдывать старый порядок, но также становилась языком освобождения и сопротивления. В афроамериканской культуре церковь часто была не только духовным, но и социальным центром, местом солидарности и политической мобилизации.'],
['5. Архитектура, скульптура, изобразительное искусство, литература, кинематограф, музыка','Архитектура Юга включает плантационные дома, сельские церкви, маленькие города, деревянные дома, кладбища, площади и пространства, связанные с памятью. В литературе эти места превращаются в символы прошлого, которое продолжает управлять настоящим. Музыка Юга — блюз, госпел, джазовые корни, кантри — стала основой американской музыкальной идентичности. Кино часто обращалось к Югу через темы войны, расизма, семейной драмы и исторического мифа. Литература же показывает, что за красивым мифом о Юге скрыты травма и конфликт.'],
['6. Философские учения периода','Философский код Юга связан не столько с академическими школами, сколько с вопросами памяти, вины, свободы, исторической ответственности и справедливости. В XX веке регион становится пространством, где абстрактные идеи равенства и прав человека проверяются реальной социальной практикой. Для понимания важны экзистенциальные мотивы: человек живет внутри истории, которую он не выбирал, но за которую вынужден отвечать.'],
['7. Концепция американской мечты','На Юге американская мечта имеет особый конфликтный характер. Для белой элиты она могла быть связана с сохранением статуса, земли, семьи и старого уклада. Для афроамериканского населения мечта означала прежде всего свободу, безопасность, образование, равные права и человеческое достоинство. Поэтому здесь особенно заметно, что «американская мечта» не была одинаковой для всех. Литература Юга показывает, что мечта может быть привилегией одних и недостижимым правом для других.'],
['8. Влияние миграции и мультикультурализма','Юг связан с Великой миграцией афроамериканцев, которые уезжали в северные и западные города, спасаясь от бедности, расового насилия и отсутствия возможностей. Но даже покидая Юг, они переносили с собой музыкальные, религиозные, языковые и семейные традиции. Так южная культура стала национальной: блюз, джаз, госпел, афроамериканская проза и политический опыт гражданских прав повлияли на всю Америку.'],
['9. Глобализация и американизация','Юг вошел в мировую культуру через музыку, литературу и кино. Блюз и джаз стали глобальными языками эмоции и импровизации. Романы о Юге стали частью мирового канона, потому что они говорят не только о региональной истории, но и о памяти, насилии, вине, достоинстве и борьбе за голос. При этом экспорт южной культуры часто сопровождался упрощением: массовая культура могла романтизировать Юг, не замечая его болезненной истории.'],
['10. Влияние политических и социальных аспектов','Юг невозможно анализировать вне политики: рабство как историческое наследие, законы сегрегации, движение за гражданские права, расовое насилие, борьба за образование и избирательные права напрямую формировали культуру. Политический конфликт здесь становился эстетическим материалом. Литература, музыка и кино не просто отражали общество, а участвовали в борьбе за пересмотр национальной памяти.'],
['11. Авторы, особенности творчества','Уильям Фолкнер показывает Юг как пространство вины, семейного распада и исторической памяти; его стиль сложен, фрагментарен, модернистски многоголосен. Маргарет Митчелл создает массовый исторический роман и миф о потерянном Юге, но этот миф требует критического чтения. Тони Моррисон возвращает в центр вытесненную афроамериканскую память, травму рабства, женский опыт и магистральную тему голоса. Ральф Эллисон и Джеймс Болдуин помогают раскрыть расовую идентичность, невидимость, достоинство и конфликт человека с обществом.']]
},
{
name:'Запад', stamp:'ЗАПАД 1957', subtitle:'Фронтир, дорога, природа, Голливуд, битники, миграция и глобальный образ США', photos:[['Дорога, фронтир и свобода движения','road'],['Голливуд и мировая массовая культура','hollywood'],['Битники, джаз, поэтический перформанс','jazz']], intro:'Запад и Тихоокеанское побережье соединяют несколько ключевых американских мифов: фронтир, свободу движения, природу, океан, дорогу, Калифорнию, Голливуд, технологическую модерность и контркультуру. Это регион, где человек будто бы может начать заново, но именно здесь мечта часто сталкивается с бедностью, одиночеством, коммерциализацией и пустотой большого обещания. В XX веке Запад становится не только географией, но и образом: дорога, экран, музыка, молодежный протест, миграция и глобальная американизация.',
blocks:[
['1. Этническое и культурное многообразие','Запад формировался как пространство пересечения коренных народов, испанского и мексиканского наследия, англоамериканской экспансии, азиатской миграции, латиноамериканских общин и внутренних мигрантов из других регионов США. Поэтому его культурная идентичность особенно гибридна. Калифорния, юго-западные штаты, Тихоокеанское побережье и Аляска показывают, что Америка не ограничивается атлантическим и европейским началом. Запад — это регион множественных границ: культурных, языковых, природных и социальных.'],
['2. Технологии и массовая культура','Запад в XX веке становится одним из главных центров массовой культуры благодаря Голливуду, киноиндустрии, музыкальной сцене, телевидению, рекламе, молодежным субкультурам и позднее технологической культуре Калифорнии. Если Северо-Восток связан с издательствами и прессой, то Запад связан с экраном, образом, визуальностью и экспортом стиля жизни. Массовая культура здесь создает миф о свободе, красоте, успехе, дороге и вечной возможности начать сначала.'],
['3. Искусство и разные направления','Искусство Запада включает литературу фронтира, социальный реализм, бит-поколение, кинематографическую культуру, поэтический перформанс, джазовую импровизацию и контркультурную эстетику. Здесь особенно важна идея движения: герой едет, бежит, ищет, меняет города, отказывается от стабильности. Битники превращают литературу в живой голос, поток речи, выступление, ритм. Стейнбек показывает социальную правду миграции, а Голливуд превращает региональные сюжеты в мировые образы.'],
['4. Религия','Религиозный код Запада неоднороден. Здесь присутствуют протестантские традиции, католическое испано-мексиканское наследие, религии мигрантских общин и особенно заметный во второй половине века интерес к восточной духовности. Для битников важны дзен-буддизм, даосизм, медитация, поиск просветления и отказ от чисто материального успеха. Поэтому Запад показывает переход от институциональной религии к индивидуальному духовному поиску.'],
['5. Архитектура, скульптура, изобразительное искусство, литература, кинематограф, музыка','Визуальный образ Запада — дороги, пустыни, горы, океан, мотели, заправки, голливудские студии, пригороды Калифорнии, кампусы и сцены клубов. Архитектура здесь часто связана не с исторической тяжестью, а с движением, открытым пространством и медийным образом. Литература Запада взаимодействует с кино и музыкой особенно тесно: битническая проза звучит как джазовая импровизация, поэзия становится выступлением, а Голливуд превращает американские сюжеты в глобальный визуальный язык.'],
['6. Философские учения периода','Философский код Запада связан с индивидуализмом, поиском подлинности, нонконформизмом, критикой потребительского общества, интересом к восточной философии и контркультурным представлением о свободе. Если прагматизм учит действию и пользе, то битническая и контркультурная среда спрашивает: достаточно ли пользы, карьеры и денег для настоящей жизни? Запад делает философский вопрос телесным и практическим: где жить, как ехать, что читать, кого любить, от чего отказаться.'],
['7. Концепция американской мечты','На Западе американская мечта связана с началом заново: приехать в Калифорнию, найти работу, стать звездой, уйти в дорогу, открыть себя, обрести свободу. Но литература показывает обратную сторону: мигранты сталкиваются с бедностью, Голливуд — с коммерческой иллюзией, дорога — с одиночеством, а свобода — с отсутствием устойчивости. Поэтому Запад — это регион самой подвижной и самой хрупкой мечты.'],
['8. Влияние миграции и мультикультурализма','Запад связан с миграцией особенно сильно: переселение во время экономических кризисов, движение рабочих в Калифорнию, латиноамериканская и азиатская миграция, коренные культуры, внутренние путешествия молодежи, битническая дорога. Мультикультурализм здесь проявляется в языке, еде, музыке, религии, городском устройстве и литературных темах. Регион показывает Америку как пространство постоянного движения, где идентичность не наследуется раз и навсегда, а собирается в пути.'],
['9. Глобализация и американизация','Запад — главный регион американизации через кино, музыку, молодежную культуру и образ жизни. Голливуд распространил по миру американские жанры, типы героев, модели любви, успеха, приключения и визуальной красоты. Позже Калифорния стала связана еще и с технологическим будущим. Через Запад Америка продавала миру мечту о свободе, дороге, славе и индивидуальном выборе. Но эта мечта была коммерческой и потому противоречивой.'],
['10. Влияние политических и социальных аспектов','Политически Запад связан с миграцией, трудовыми конфликтами, правами меньшинств, молодежным протестом, антивоенными настроениями, свободой слова, сексуальной революцией и критикой потребления. В литературе это проявляется через героя, который не хочет быть частью стандартной карьеры и семейной модели. Бит-поколение и контркультура делают личный выбор политическим жестом: как жить — значит против чего-то выступать.'],
['11. Авторы, особенности творчества','Джон Стейнбек показывает социальную правду мигрантов, бедность, труд и достоинство человека в экономическом кризисе. Джек Керуак создает прозу дороги, спонтанности и духовного поиска. Аллен Гинзберг превращает поэзию в публичный крик против конформизма и потребительского общества. Джек Лондон, хотя относится к рубежу XIX–XX веков, важен как предшественник тем фронтира, природы, self-made man, труда и критики капитализма. Для Запада характерны движение, открытое пространство, эксперимент, перформативность и связь литературы с кино и музыкой.']]
}
];

const periods=[['Потерянное поколение и модернизм','1920–1930-е: Фицджеральд, Хемингуэй, Фолкнер. Кризис американской мечты, травма войны, одиночество, урбанизация, модернистские формы.'],['Социальный реализм и литература Великой депрессии','1930–1940-е: Стейнбек, Ричард Райт, частично Фолкнер. Бедность, труд, миграция, расовая проблема, экономическая система.'],['Послевоенная проза и отчуждение','1940–1950-е: Сэлинджер, Эллисон, Воннегут. Поиск идентичности, критика конформизма, подростковый голос, травма войны.'],['Бит-поколение и контркультура','1950–1960-е: Керуак, Гинзберг, Берроуз. Дорога, джаз, дзен-буддизм, свобода, перформанс, протест.'],['Мультикультурная и афроамериканская литература','1960–1990-е: Моррисон, Болдуин, Эллисон, Уокер. Расовая память, гражданские права, женский голос, историческая травма.']];
const authors=[['Ф. С. Фицджеральд','«Великий Гэтсби», «Ночь нежна». Кризис американской мечты, деньги, статус, иллюзия успеха.'],['Эрнест Хемингуэй','«Прощай, оружие!», «И восходит солнце», «Старик и море». Лаконизм, травма войны, код достоинства.'],['Уильям Фолкнер','«Шум и ярость», «Авессалом, Авессалом!». Историческая память Юга, вина, расовый конфликт.'],['Джон Стейнбек','«Гроздья гнева», «О мышах и людях». Социальный реализм, миграция, бедность, труд.'],['Дж. Д. Сэлинджер','«Над пропастью во ржи», «Фрэнни и Зуи». Отчуждение, подростковый голос, духовный поиск.'],['Джек Керуак','«На дороге». Бит-поколение, дорога, спонтанная проза, поиск свободы.'],['Аллен Гинзберг','«Вопль». Поэтический перформанс, протест, джазовый ритм, контркультура.'],['Тони Моррисон','«Возлюбленная», «Песнь Соломона». Афроамериканская память, травма рабства, женский голос.']];
let active=0, activeAuthor=authors[0], messages=[{role:'assistant',text:'Выберите автора и задайте вопрос о произведении, эпохе или культурном коде.'}];
