function renderPassport(){const r=regions[active],m=meta(r);let spread=document.getElementById('passportSpread');if(spread){spread.classList.remove('turn');void spread.offsetWidth;spread.classList.add('turn')}el('pfNo').textContent=m.no;el('pfRegion').textContent=r.name.toUpperCase();el('pfIdentity').textContent=m.id;el('pfPlace').textContent=m.place;el('pfIssue').textContent=m.issue;el('pfSummary');el('pfRegion');el('nationality');el('pfNo');el('passTitle').textContent=r.name;el('passSub').textContent=r.subtitle;el('passStamp').textContent=r.stamp;el('passportSummary').textContent=r.intro;el('passportPhoto').className='passport-photo-frame '+m.photo;el('passportPhoto').innerHTML='<span style="position:absolute;left:-9999px">'+r.name+'</span>';el('photos').innerHTML='';r.photos.forEach(p=>{let d=document.createElement('div');d.className='photo '+p[1];d.innerHTML='<span>'+p[0]+'</span>';el('photos').appendChild(d)});el('visitedPlaces').innerHTML='';m.places.forEach(x=>{let d=document.createElement('div');d.className='check-row';d.innerHTML='<span class="check">✓</span><span>'+x+'</span>';el('visitedPlaces').appendChild(d)});el('artifacts').innerHTML='';m.arts.forEach(a=>{let d=document.createElement('div');d.className='artifact';d.innerHTML='<b>'+a[0]+'</b><span>'+a[1]+'</span>';el('artifacts').appendChild(d)});el('signatures').innerHTML='';m.sign.forEach(x=>{let s=document.createElement('span');s.className='signature';s.textContent=x;el('signatures').appendChild(s)});el('blocks').innerHTML='';r.blocks.forEach(p=>{let d=document.createElement('div');d.className='block';d.innerHTML='<h4>'+p[0]+'</h4><div>'+p[1]+'</div>';el('blocks').appendChild(d)});el('regionButtons').innerHTML='';regions.forEach((x,i)=>{let b=document.createElement('button');b.className='regionBtn'+(i===active?' active':'');b.innerHTML='<strong>'+x.stamp+'</strong><span>'+x.name+' — '+meta(x).id+'</span>';b.onclick=()=>{active=i;renderPassport()};el('regionButtons').appendChild(b)});el('dots').innerHTML='';regions.forEach((x,i)=>{let d=document.createElement('button');d.className='dot'+(i===active?' active':'');d.onclick=()=>{active=i;renderPassport()};el('dots').appendChild(d)});el('counter').textContent='страница '+(active+1)+' / '+regions.length;el('prev').disabled=active===0;el('next').disabled=active===regions.length-1;el('prev').onclick=()=>{if(active>0){active--;renderPassport()}};el('next').onclick=()=>{if(active<regions.length-1){active++;renderPassport()}}}
const authorMail={
  'Ф. С. Фицджеральд':{place:'Нью-Йорк · Лонг-Айленд · эпоха джаза',stamp:'JAZZ AGE\\n1925',pic:['pic-city','pic-jazz'],sign:'F. Scott',tags:['американская мечта','статус','городская иллюзия'],voice:'Я бы начал с того, что блеск Америки почти всегда стоит рядом с пустотой. Деньги дают вход на вечеринку, но не гарантируют принадлежности к миру, который эту вечеринку устроил.',dream:'Американская мечта в моём мире выглядит как витрина: она сияет, обещает новую жизнь, но за стеклом остаются класс, происхождение и одиночество.',war:'После войны герой часто возвращается не победителем, а человеком, который слишком рано понял цену красивых лозунгов.',race:'Мой фокус чаще направлен на класс и деньги, но сама структура исключения показывает, что Америка делит людей не только по таланту, а по происхождению, статусу и доступу.',road:'Дорога здесь не спасает окончательно: она скорее ведёт к новой иллюзии, если человек не понимает, от чего именно бежит.'},
  'Эрнест Хемингуэй':{place:'Оук-Парк · Париж · фронт · Ки-Уэст',stamp:'FIELD POST\\n1940',pic:['pic-type','pic-road'],sign:'E. Hemingway',tags:['война','лаконизм','достоинство'],voice:'Писать нужно прямо. Не украшать боль. Если человек потерял опору, фраза должна держаться так, как он сам пытается держаться.',dream:'Мечта проверяется не словами об успехе, а тем, сохраняет ли человек достоинство, когда успех разрушен.',war:'Война не делает людей проще. Она отрезает лишнее и оставляет то, что нельзя спрятать: страх, верность, усталость, привычку молчать.',race:'Чужая боль не должна становиться декорацией. Писатель обязан видеть человека, а не удобный символ.',road:'Движение важно, но дорога не лечит сама по себе. Она только показывает, кто способен идти дальше без фальши.'},
  'Уильям Фолкнер':{place:'Миссисипи · Йокнапатофа · память Юга',stamp:'SOUTH\\n1936',pic:['pic-south','pic-book'],sign:'W. Faulkner',tags:['Юг','память','вина'],voice:'Прошлое не лежит позади. Оно говорит через дома, фамилии, молчание семьи и через то, о чём общество делает вид, что забыло.',dream:'Американская мечта на Юге сталкивается с наследством, которое нельзя отменить одним личным усилием.',war:'Война и поражение остаются в языке поколений: люди живут не только собственной биографией, но и чужой исторической виной.',race:'Расовый конфликт нельзя вынести за скобки. Он находится в самой земле, в памяти семьи, в законе, в страхе и в попытках забыть то, что забыть невозможно.',road:'Переезд может сменить адрес, но не всегда освобождает от прошлого. Иногда человек везёт свой округ внутри себя.'},
  'Джон Стейнбек':{place:'Калифорния · дороги мигрантов · Великая депрессия',stamp:'MIGRANT\\n1939',pic:['pic-road','pic-type'],sign:'J. Steinbeck',tags:['миграция','труд','бедность'],voice:'Сначала нужно увидеть людей, которых статистика превращает в массу. У них есть руки, дети, грузовик, голод и право на достоинство.',dream:'Мечта становится настоящей только тогда, когда она доступна не одному счастливчику, а семье, рабочему, мигранту, человеку без защиты.',war:'Кризис мирного времени тоже похож на войну: люди теряют дом, язык уверенности и веру в справедливый рынок.',race:'Социальная правда неполна без вопроса о том, кого система заранее ставит в уязвимое положение.',road:'Дорога у меня не романтическая. Это пыль, поломка машины, голод и надежда, которая держится вопреки экономике.'},
  'Дж. Д. Сэлинджер':{place:'Нью-Йорк · послевоенная Америка · подростковый голос',stamp:'PRIVATE\\n1951',pic:['pic-city','pic-book'],sign:'J. D. S.',tags:['отчуждение','подростковый голос','фальшь'],voice:'Самое трудное — не потерять живой голос среди взрослых слов. Иногда честность звучит нервно, неловко и слишком лично.',dream:'Американская мечта может выглядеть как спектакль, где все делают вид, что понимают правила. Подросток первым замечает фальшь.',war:'После войны травма может прятаться в раздражении, молчании и невозможности вернуться к нормальной речи.',race:'Если общество строит нормальность на исключении других, чувствительный герой ощущает эту фальшь даже тогда, когда не умеет назвать её политически.',road:'Побег по городу не всегда свобода. Иногда это попытка найти место, где можно говорить без маски.'},
  'Джек Керуак':{place:'дороги США · Нью-Йорк · Сан-Франциско',stamp:'ON THE ROAD\\n1957',pic:['pic-road','pic-jazz'],sign:'Jack',tags:['бит-поколение','дорога','свобода'],voice:'Ответ не в кабинете. Он в дороге, в ритме разговора, в ночном автобусе, в джазе, в попытке жить быстрее, чем тебя успеют оформить.',dream:'Мечта для битников — не дом с газоном, а возможность выйти из предписанного маршрута и услышать собственный ритм.',war:'Послевоенная стабильность многим казалась клеткой. Бунт возник не от пустоты, а от усталости перед готовыми правилами.',race:'Бит-культура многое взяла у джаза и афроамериканской городской энергии, поэтому честный разговор обязан признавать источник этого ритма.',road:'Дорога — главный сюжет: она даёт свободу, но одновременно проверяет, не путает ли герой движение с настоящим смыслом.'},
  'Аллен Гинзберг':{place:'Нью-Йорк · Сан-Франциско · поэтический перформанс',stamp:'HOWL\\n1956',pic:['pic-jazz','pic-city'],sign:'Allen',tags:['протест','перформанс','контркультура'],voice:'Письмо должно звучать вслух. Если эпоха давит человека, строка имеет право кричать, сбиваться, повторяться и превращаться в публичное свидетельство.',dream:'Официальная мечта часто исключает тех, кто не вписывается в норму. Поэзия возвращает им голос.',war:'Холодная война, страх и контроль создают язык тревоги. Поэт отвечает не тишиной, а открытым дыханием строки.',race:'Нельзя говорить о свободе, не замечая, кому она запрещена законом, привычкой или полицейской практикой.',road:'Дорога, джаз, сцена и город превращают литературу в действие, а не только в напечатанную страницу.'},
  'Тони Моррисон':{place:'Огайо · Нью-Йорк · афроамериканская память',stamp:'MEMORY\\n1987',pic:['pic-south','pic-book'],sign:'T. Morrison',tags:['память','рабство','женский голос'],voice:'Самое важное — вернуть язык тем, кого история пыталась превратить в отсутствие. Память болезненна, но без неё невозможно собрать себя.',dream:'Американская мечта неполна, если не говорит о тех, чьё тело и труд были сделаны ценой чужого благополучия.',war:'Главная травма может быть не только на фронте. Насилие истории живёт в семье, материнстве, имени, доме и памяти.',race:'Расовая память — не тема сбоку, а центр американского опыта. Без неё рассказ о XX веке становится неполным и нечестным.',road:'Переезд не отменяет памяти. Человек может сменить город, но история всё равно ищет язык, чтобы быть услышанной.'}
};
function safeText(v){return String(v||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function stampClassName(m){let cls=(m&&m.stampClass)||'stamp-1920';return /^[a-z0-9_-]+$/i.test(cls)?cls:'stamp-1920'}
function stampHTML(m){let raw=String((m&&m.stamp)||'U.S. MAIL\nXX CENTURY').split(/\n/);let title=raw[0]||'U.S. MAIL';let year=raw.slice(1).join(' ')||'XX CENTURY';return '<span class="stamp-main">'+safeText(title)+'</span><span class="stamp-year">'+safeText(year)+'</span><span class="stamp-country">U.S. POSTAGE</span>'}
function refreshUserPostcardVisuals(m){let pics=document.querySelectorAll('.postcard-user .mini-picture');if(pics[0]){pics[0].className='mini-picture '+((m&&m.pic&&m.pic[0])||'pic-city');let s=pics[0].querySelector('span');if(s)s.textContent='эпоха'}if(pics[1]){pics[1].className='mini-picture '+((m&&m.pic&&m.pic[1])||'pic-book');let s=pics[1].querySelector('span');if(s)s.textContent='код'}}
function getMailMeta(){return authorMail[activeAuthor[0]]||authorMail['Ф. С. Фицджеральд']}
function themeKey(text){let q=(text||'').toLowerCase();if(/мечт|успех|деньг|богат|карьер|статус/.test(q))return'dream';if(/войн|травм|фронт|кризис|насил|потер/.test(q))return'war';if(/рас|рабств|сегрегац|гражданск|черн|афро/.test(q))return'race';if(/дорог|свобод|бит|джаз|контркультур|переезд/.test(q))return'road';return'voice'}
function renderAuthorHeader(){let m=getMailMeta();el('chatAuthor').textContent=activeAuthor[0];el('postAddressTo').textContent='Адрес: '+m.place;let stamp=el('userStamp');if(stamp){stamp.className='stamp-post '+stampClassName(m);stamp.innerHTML=stampHTML(m)}refreshUserPostcardVisuals(m);document.querySelectorAll('.postcard-author-btn').forEach((b,i)=>b.classList.toggle('active',authors[i]===activeAuthor))}
function renderChat(){el('authorList').innerHTML='';authors.forEach((a,i)=>{let m=authorMail[a[0]]||authorMail['Ф. С. Фицджеральд'];let d=document.createElement('button');d.className='postcard-author-btn'+(a===activeAuthor?' active':'');d.innerHTML='<b>'+safeText(a[0])+'</b><span>'+safeText(m.place)+'</span><span style="margin-top:6px">'+m.tags.map(t=>'#'+safeText(t)).join(' ')+'</span>';d.onclick=()=>{activeAuthor=a;renderAuthorHeader();el('mailStatus').textContent='✉ адресат выбран';};el('authorList').appendChild(d)});el('send').onclick=sendChat;renderAuthorHeader()}
function buildReply(sender,theme,letter){let m=getMailMeta(),key=themeKey(theme+' '+letter),intro=m[key]||m.voice;let ask=safeText(letter.length>190?letter.slice(0,190)+'…':letter);return `<section class="postcard postcard-reply"><div class="postcard-top"><div><div class="postcard-kicker">reply from author</div><div class="postcard-title">Ответная открытка</div><div class="postcard-address">${safeText(m.place)}</div></div><div class="stamp-post blue ${stampClassName(m)}">${stampHTML(m)}</div></div><div class="postcard-picture-row"><div class="mini-picture ${m.pic[0]}"><span>эпоха</span></div><div class="mini-picture ${m.pic[1]}"><span>код</span></div></div><div class="reply-letter"><p>Дорогой читатель, ${safeText(sender)}.</p><p>Я получил открытку: «${ask}»</p><p>${safeText(intro)}</p><p>${safeText(m.voice)} В контексте литературы США XX века это важно потому, что писатель здесь не просто рассказывает частную историю: он фиксирует давление эпохи — рынок, войну, расовые границы, город, дорогу, семью, одиночество и желание быть услышанным.</p><p class="reply-sign">${safeText(m.sign)}</p></div><div class="postcard-meta">${m.tags.map(t=>'<span>'+safeText(t)+'</span>').join('')}<span>учебная реконструкция</span></div></section>`}
function sendChat(){let letter=el('postLetter').value.trim(),sender=el('postSender').value.trim()||'читатель из XXI века',theme=el('postTheme').value;if(!letter){el('postAlert').classList.add('show');return}el('postAlert').classList.remove('show');let m=getMailMeta();el('mailStatus').textContent='✓ открытка доставлена';let sent=`<div class="sent-note"><b>Открытка отправлена.</b><br>Адресат: ${safeText(activeAuthor[0])}. Тема: ${safeText(theme)}. Письмо сохранено как часть переписки.</div>`;el('replyWrap').innerHTML=sent+buildReply(sender,theme,letter)}
function renderMessages(){renderChat()}
function renderDB(){['Этническое и культурное многообразие','Технологии и массовая культура','Искусство и разные направления','Религия','Архитектура, литература, кинематограф, музыка','Философские учения периода','Американская мечта','Миграция и мультикультурализм','Глобализация и американизация','Политические и социальные аспекты'].forEach(x=>{let d=document.createElement('details');d.innerHTML='<summary>'+x+'</summary><p>Раздел показывает, как этот компонент проявлялся в культуре, литературе, искусстве и общественной жизни США XX века.</p>';el('dbCulture').appendChild(d)});periods.forEach(x=>{let d=document.createElement('details');d.innerHTML='<summary>'+x[0]+'</summary><p>'+x[1]+'</p>';el('dbPeriods').appendChild(d)});authors.forEach(x=>{let d=document.createElement('details');d.innerHTML='<summary>'+x[0]+'</summary><p>'+x[1]+'</p>';el('dbAuthors').appendChild(d)})}
initTabs();renderPassport();renderChat();renderDB();initMap();

