const profiles=[{"id": "city", "name": "Северо-Восток", "route": "Нью-Йорк, Бостон, издательства, модернизм", "stats": {"fame": 8, "money": 4, "craft": 7, "integrity": 7, "network": 8, "risk": 2, "trauma": 1, "audience": 6}, "tags": ["мегаполис", "иммиграция", "модернизм"]}, {"id": "midwest", "name": "Средний Запад", "route": "фермы, Чикаго, Детройт, трудовая этика", "stats": {"fame": 5, "money": 5, "craft": 8, "integrity": 8, "network": 4, "risk": 2, "trauma": 1, "audience": 5}, "tags": ["труд", "фермерская Америка", "индустрия"]}, {"id": "south", "name": "Юг", "route": "память, расовая история, блюз, религия", "stats": {"fame": 4, "money": 3, "craft": 8, "integrity": 9, "network": 3, "risk": 5, "trauma": 3, "audience": 4}, "tags": ["память", "расовая история", "блюз"]}, {"id": "west", "name": "Запад", "route": "Калифорния, Голливуд, дорога, контркультура", "stats": {"fame": 5, "money": 4, "craft": 6, "integrity": 7, "network": 5, "risk": 3, "trauma": 1, "audience": 7}, "tags": ["дорога", "Голливуд", "контркультура"]}];const episodes=[{"year":"1910","title":"Редакция большого города","scene":"Ты только приехал в Нью-Йорк и приносишь рассказ в журнальную редакцию. За окном — иммигрантские кварталы, фабрики, дешёвые комнаты и вывески на разных языках. Редактор готов напечатать текст, но просит убрать бедность и тяжёлый труд: читатель, по его словам, хочет блеска города, а не его изнанки.","fact":"В начале XX века американская массовая пресса быстро росла, но вместе с аудиторией усиливалась зависимость автора от редактора, рынка и вкуса среднего читателя.","choices":[{"text":"Оставить в рассказе фабрики, перенаселённые дома и речь иммигрантов.","verdict":"Честный дебют","result":"Мини-рецензия: выбор делает текст менее удобным для журнала, зато точнее передаёт город начала века. В нём появляется не открытка с небоскрёбами, а живая Америка труда, приезда и неравенства. Такой ход укрепляет авторский голос, хотя карьерный старт становится труднее.","effects":{"fame":2,"craft":4,"integrity":5,"risk":2,"audience":2},"tags":["городской реализм","иммиграция"]},{"text":"Переписать рассказ как лёгкую сцену о театрах, витринах и вечерних прогулках.","verdict":"Удобный компромисс","result":"Мини-рецензия: это аккуратный вход в профессию, но текст теряет социальную плотность. Он может понравиться редактору и быстро дойти до читателя, однако город в нём становится декорацией, а не историческим опытом.","effects":{"fame":3,"money":4,"network":3,"integrity":-2,"craft":-1,"audience":4},"tags":["журнальный рынок","компромисс"]},{"text":"Отказаться от публикации и начать длинный роман о семье переселенцев.","verdict":"Медленный старт","result":"Мини-рецензия: решение смелое, но не гарантирует результата. Ты выигрываешь время для наблюдения и формы, зато теряешь раннюю аудиторию. Для большого романа нужны не только убеждения, но и дисциплина.","effects":{"fame":-1,"money":-2,"craft":5,"integrity":3,"risk":1,"audience":-1},"tags":["большая форма","дисциплина"]}]},{"year":"1916","title":"Поезд на север","scene":"На вокзале южного города семьи покупают билеты в Чикаго, Детройт и Нью-Йорк. Люди уезжают от законов Джима Кроу, угроз насилия и бедной работы на земле. Издатель предупреждает: тема расовой миграции может вызвать споры и отпугнуть часть читателей.","fact":"Великое переселение афроамериканцев из южных штатов продолжалось десятилетиями и серьёзно изменило культуру городов Севера, Среднего Запада и Запада.","choices":[{"text":"Сделать миграцию фоном для истории белого журналиста, который ищет сенсацию.","verdict":"Поверхностный ракурс","result":"Мини-рецензия: такой текст может быть динамичным, но главный опыт остаётся чужим и непрояснённым. История переезда превращается в фон для чужой карьеры, поэтому сила темы ослабевает.","effects":{"fame":3,"money":2,"network":2,"integrity":-4,"craft":-1,"audience":3},"tags":["сенсационность","спорный ракурс"]},{"text":"Поехать в районы прибытия, записывать разговоры, быт, страхи и надежды переселенцев.","verdict":"Точное наблюдение","result":"Мини-рецензия: выбор требует труда и осторожности. Текст становится убедительнее, потому что опирается на голоса людей, а не на газетный пересказ. Так литература приближается к документу, не теряя художественной силы.","effects":{"fame":2,"craft":5,"integrity":5,"risk":2,"audience":3,"trauma":1},"tags":["Великое переселение","устная история"]},{"text":"Отложить тему и написать роман о личном успехе без расового конфликта.","verdict":"Безопасное молчание","result":"Мини-рецензия: это снижает риск, но обедняет картину века. Личная история успеха без социального контекста звучит проще, чем реальная Америка, где дорога к будущему для разных людей была неравной.","effects":{"money":3,"risk":-2,"integrity":-3,"craft":0,"audience":2},"tags":["безопасный сюжет"]}]},{"year":"1917","title":"Война и первая травма века","scene":"США вступают в Первую мировую войну. Молодые писатели идут в армию, работают водителями санитарных машин, корреспондентами или наблюдателями. В редакциях ждут патриотических текстов, но письма с фронта говорят о страхе, грязи, ранениях и усталости.","fact":"Опыт Первой мировой войны стал важной основой литературы «потерянного поколения», где война показана без романтической героизации.","choices":[{"text":"Написать бодрый патриотический очерк о славе и долге.","verdict":"Официальный тон","result":"Мини-рецензия: текст легко вписывается в военное настроение, но звучит слишком гладко для опыта окопов и госпиталей. Он может быть востребован сразу, однако позже будет выглядеть как документ времени, а не сильная литература.","effects":{"fame":3,"money":2,"network":3,"integrity":-3,"craft":-1,"risk":-1},"tags":["патриотическая пресса"]},{"text":"Показать войну через короткие сцены: госпиталь, потерянные письма, молчание после боя.","verdict":"Сдержанная правда","result":"Мини-рецензия: выбор сильный, потому что не спорит громкими лозунгами, а показывает последствия войны на уровне тела и памяти. Такая проза ближе к будущей манере Хемингуэя: меньше объяснений, больше внутреннего напряжения.","effects":{"fame":3,"craft":5,"integrity":5,"trauma":3,"audience":2},"tags":["потерянное поколение","антивоенная проза"]},{"text":"Не писать о фронте вообще и уйти в светскую хронику.","verdict":"Уход от темы","result":"Мини-рецензия: пауза может защитить автора, но век не исчезает из-за молчания. Читатель всё равно будет искать язык для травмы, и если его не дать, место займут другие голоса.","effects":{"money":2,"risk":-2,"trauma":-1,"integrity":-2,"craft":0},"tags":["молчание"]}]},{"year":"1919","title":"После войны: страх перед радикалами","scene":"Страна возвращается к мирной жизни, но вместе с этим растут забастовки, тревога перед социализмом и подозрительность к иностранцам. Тебе предлагают написать о рабочем собрании. Полиция следит за активистами, а редактор боится обвинений в симпатиях к радикалам.","fact":"После Первой мировой войны в США прошла первая «красная паника»: усилились антирадикальные настроения, преследования левых активистов и давление на иммигрантские сообщества.","choices":[{"text":"Сделать материал о рабочих требованиях, не превращая людей в угрозу.","verdict":"Взвешенный репортаж","result":"Мини-рецензия: решение выглядит профессионально: оно не романтизирует протест, но и не превращает рабочих в карикатуру. Такой текст показывает конфликт труда и капитала как часть американской истории.","effects":{"craft":4,"integrity":4,"risk":3,"audience":2,"network":-1},"tags":["рабочее движение","репортаж"]},{"text":"Написать резкий памфлет, где все предприниматели названы врагами народа.","verdict":"Публицистический перегиб","result":"Мини-рецензия: энергия текста заметна, но обобщение упрощает конфликт. Памфлет может привлечь сторонников, однако художественная сложность уступает лозунгу.","effects":{"fame":2,"integrity":1,"risk":5,"craft":-2,"network":-3},"tags":["памфлет","высокий риск"]},{"text":"Согласиться с редактором и представить рабочих как опасную толпу.","verdict":"Конъюнктурный текст","result":"Мини-рецензия: это безопасно для редакции, но плохо для автора. Материал подменяет наблюдение страхом и теряет доверие там, где требовалась точность.","effects":{"money":3,"network":3,"risk":-2,"integrity":-5,"craft":-2,"audience":1},"tags":["конъюнктура"]}]},{"year":"1920","title":"Эпоха джаза и быстрый успех","scene":"Твой рассказ замечает модный журнал. Нью-Йорк шумит вечеринками, рекламой, автомобилями, танцами и разговорами о богатстве. Агент предлагает серию текстов о молодых людях, которые живут быстро и тратят легко. Но за блеском уже видны классовые границы и усталость.","fact":"1920-е годы в США связаны с ростом массового потребления, городской культуры, джаза, рекламы и одновременно с критикой пустоты материального успеха.","choices":[{"text":"Принять заказ и писать только о блестящей стороне вечеринок.","verdict":"Глянцевый успех","result":"Мини-рецензия: текст быстро входит в моду, но рискует стать приложением к рекламе эпохи. Вечеринка есть, а вопроса о цене этого блеска пока нет.","effects":{"fame":5,"money":5,"network":4,"audience":5,"integrity":-3,"craft":-1},"tags":["эпоха джаза","глянец"]},{"text":"Показать праздник вместе с одиночеством, долгами и желанием казаться выше своего происхождения.","verdict":"Двойное дно","result":"Мини-рецензия: сильный выбор: ты не отвергаешь красоту эпохи, но показываешь её внутреннюю цену. Так появляется материал для романа о мечте, которая сияет именно потому, что может оказаться недостижимой.","effects":{"fame":4,"craft":5,"integrity":4,"audience":4,"trauma":1},"tags":["американская мечта","критика богатства"]},{"text":"Уехать из города и писать о провинциальной жизни без связи с новой массовой культурой.","verdict":"Осознанная дистанция","result":"Мини-рецензия: дистанция помогает не раствориться в моде, но полный отказ от городской культуры сужает масштаб. Век меняется через рекламу, джаз и экран, и эти силы всё равно вернутся в текст.","effects":{"craft":2,"integrity":2,"risk":-1,"fame":-1,"audience":-1},"tags":["провинциальная тема"]}]},{"year":"1925","title":"Старый дом на Юге","scene":"Тебя приглашают в южный городок написать семейную сагу. В старом доме хранят портреты, письма, рассказы о Гражданской войне и молчание о рабстве. Местные ждут красивой легенды о благородном прошлом, но архив семьи говорит о долгах, насилии и самообмане.","fact":"Южная литература XX века часто обращалась к памяти рабства, Гражданской войны, сегрегации, семейного распада и конфликту между мифом о прошлом и реальностью.","choices":[{"text":"Написать роман как ностальгическую легенду о прекрасном старом Юге.","verdict":"Украшенная память","result":"Мини-рецензия: текст может быть эффектным и понятным, но он уходит от главной боли региона. Когда прошлое превращается только в декорацию, литература теряет моральную глубину.","effects":{"fame":3,"money":3,"audience":3,"integrity":-5,"craft":-1},"tags":["плантационный миф"]},{"text":"Собрать семейную историю через разные голоса, противоречия и обрывки памяти.","verdict":"Сложная сага","result":"Мини-рецензия: выбор ближе к большой южной прозе: прошлое здесь не объясняется одной фразой, а давит на каждое поколение. Такой текст труднее читать, но именно в этой трудности появляется правда региона.","effects":{"craft":6,"integrity":5,"fame":2,"risk":2,"audience":1},"tags":["южная готика","семейная память"]},{"text":"Сделать действие любовной историей и оставить расовые конфликты за кадром.","verdict":"Неполная мелодрама","result":"Мини-рецензия: роман может быть эмоциональным, но из него исчезает историческая причина напряжения. Любовь на Юге XX века редко существует вне класса, расы, религии и семейной памяти.","effects":{"money":3,"audience":4,"integrity":-3,"craft":0,"risk":-1},"tags":["мелодрама"]}]},{"year":"1929","title":"Обвал на Уолл-стрит","scene":"После биржевого краха знакомые теряют работу, издатель закрывает серию книг, а газеты спорят, кто виноват. Тебе предлагают написать роман о человеке, который всё потерял за одну неделю. Вопрос в том, будет ли это личная драма или история системы, где мечта зависела от кредита, биржи и удачи.","fact":"Крах 1929 года стал началом Великой депрессии, изменившей американскую литературу, журналистику, театр, фотографию и социальное искусство 1930-х годов.","choices":[{"text":"Показать героя как единственного виновника собственного падения.","verdict":"Узкая мораль","result":"Мини-рецензия: такая версия проста и драматична, но слишком удобна. Она не замечает, что личный крах в 1930-е часто был связан с общей экономической катастрофой.","effects":{"fame":2,"money":2,"integrity":-3,"craft":-1,"audience":2},"tags":["индивидуальная вина"]},{"text":"Соединить личный крах с банками, безработицей, очередями за едой и распадом семьи.","verdict":"Социальная глубина","result":"Мини-рецензия: выбор делает историю шире одной биографии. В таком тексте человек не исчезает за статистикой, а статистика перестаёт быть сухой: она входит в дом, разговор и тело героя.","effects":{"craft":5,"integrity":5,"risk":2,"audience":3,"trauma":2},"tags":["Великая депрессия","социальная проза"]},{"text":"Перейти к комедийным рассказам, чтобы дать читателю отдых от бедности.","verdict":"Развлекательный уход","result":"Мини-рецензия: развлечение в кризис тоже нужно, но если оно полностью закрывает реальность, текст быстро стареет. Смех сильнее, когда он понимает, от чего именно защищает читателя.","effects":{"money":4,"audience":4,"risk":-2,"integrity":-2,"craft":1},"tags":["эскапизм"]}]},{"year":"1933","title":"Государственный архив голосов","scene":"Во время Нового курса появляются программы поддержки культуры. Тебе предлагают участвовать в проекте, где нужно записывать рассказы рабочих, бывших рабов, фермеров, переселенцев и жителей малых городов. Друг советует отказаться: государственный проект, по его мнению, сделает автора зависимым.","fact":"В 1930-е годы Федеральный писательский проект и другие инициативы Нового курса поддерживали авторов и собирали важные устные свидетельства о жизни разных групп населения США.","choices":[{"text":"Отказаться из принципа и писать только за частные журналы.","verdict":"Независимость с потерями","result":"Мини-рецензия: позиция понятна, но она лишает тебя доступа к редким голосам. Независимость важна, однако в годы кризиса государственные культурные проекты дали литературе большой документальный материал.","effects":{"integrity":2,"risk":-1,"money":1,"craft":-1,"audience":-1},"tags":["частный рынок"]},{"text":"Принять участие и записывать свидетельства максимально точно, без украшения.","verdict":"Архивная честность","result":"Мини-рецензия: это сильный выбор для автора, который хочет понимать страну не по лозунгам. Встречи с разными людьми расширяют язык, фактуру и ответственность текста.","effects":{"craft":5,"integrity":5,"network":2,"audience":2,"money":1},"tags":["Новый курс","устные свидетельства"]},{"text":"Использовать проект как способ получить зарплату, но записи вести формально.","verdict":"Пустая занятость","result":"Мини-рецензия: деньги помогают выжить, но литературной ценности почти не появляется. Формальная запись превращает живой опыт в бумагу без голоса.","effects":{"money":4,"network":1,"integrity":-3,"craft":-3,"audience":-1},"tags":["формальность"]}]},{"year":"1936","title":"Пыльные дороги равнин","scene":"Засуха и пыльные бури выталкивают семьи с ферм. На дорогах появляются грузовики с матрасами, детьми и всем имуществом. Газета просит очерк о «бедных неудачниках», но ты видишь не лень, а экологическую и экономическую катастрофу.","fact":"Пыльный котёл и Великая депрессия стали основой для литературы, фотографии и журналистики о миграции фермеров, бедности и незащищённости труда.","choices":[{"text":"Написать о переселенцах как о людях с достоинством, памятью и правом на труд.","verdict":"Человеческий масштаб","result":"Мини-рецензия: выбор точный: бедность не превращается в зрелище, а люди не исчезают за диагнозом общества. Такой текст может спорить с предрассудками и одновременно оставаться художественным.","effects":{"craft":5,"integrity":5,"audience":4,"risk":2,"trauma":2},"tags":["Пыльный котёл","миграция фермеров"]},{"text":"Сделать из дороги приключение без голода, унижения и трудовых конфликтов.","verdict":"Облегчённая версия","result":"Мини-рецензия: дорога получается кинематографичной, но слишком чистой. Без лагерей, дешёвого труда и семейной тревоги история 1930-х теряет опору.","effects":{"money":3,"audience":3,"integrity":-4,"craft":-1,"risk":-1},"tags":["приключенческий тон"]},{"text":"Сфокусироваться только на статистике урожая и цен, почти без людей.","verdict":"Сухой документ","result":"Мини-рецензия: факты нужны, но без человеческой судьбы они не становятся литературой. Читатель понимает масштаб бедствия, но не чувствует, что оно делает с семьёй и языком.","effects":{"craft":1,"integrity":2,"audience":-2,"fame":-1},"tags":["документальность"]}]},{"year":"1938","title":"Голливуд покупает роман","scene":"Студия в Калифорнии предлагает большие деньги за экранизацию. Продюсер хочет убрать сложный финал, упростить расовые и классовые мотивы, добавить красивую любовную линию. Ты можешь получить аудиторию, но часть смысла исчезнет на монтажном столе.","fact":"Голливуд в XX веке стал одним из главных механизмов американской массовой культуры: он расширял аудиторию литературных сюжетов, но часто менял их под коммерческий формат.","choices":[{"text":"Продать права без условий: фильм сделает имя известным.","verdict":"Сделка с потерями","result":"Мини-рецензия: выбор приносит деньги и славу, но авторский контроль почти исчезает. Это не провал, но риск: публика может запомнить упрощённую версию вместо книги.","effects":{"fame":6,"money":7,"network":5,"integrity":-4,"craft":-1,"audience":6},"tags":["Голливуд","экранизация"]},{"text":"Отказаться от студии и сохранить роман без изменений.","verdict":"Жёсткая защита текста","result":"Мини-рецензия: решение сохраняет художественную цельность, но закрывает путь к массовой аудитории. Иногда отказ становится частью репутации, однако он не всегда помогает книге жить шире.","effects":{"integrity":5,"craft":2,"money":-3,"fame":-1,"network":-2},"tags":["авторский контроль"]},{"text":"Согласиться на экранизацию, но добиваться сохранения главного конфликта и финала.","verdict":"Рабочий баланс","result":"Мини-рецензия: это зрелый вариант. Ты признаёшь силу кино, но не отдаёшь ему смысл полностью. Компромисс остаётся компромиссом, зато история получает шанс дойти до новой публики без полного упрощения.","effects":{"fame":4,"money":4,"network":4,"integrity":2,"audience":5,"risk":1},"tags":["кино и литература","баланс"]}]},{"year":"1941","title":"Писатель во время Второй мировой","scene":"После вступления США во Вторую мировую войну редакции ждут текстов о единстве страны. Тебе поручают серию очерков о заводах, солдатах и семьях, которые ждут писем. Но на производстве работают женщины, афроамериканцы, мигранты, и их вклад не всегда признают одинаково.","fact":"Вторая мировая война усилила военную журналистику, государственную пропаганду, промышленную мобилизацию и одновременно изменила роль женщин и меньшинств в общественной жизни США.","choices":[{"text":"Написать только о фронтовом героизме, не касаясь тыла.","verdict":"Половина картины","result":"Мини-рецензия: текст будет понятным и патриотичным, но оставит за кадром огромный труд заводов, семей и женщин. Война в культуре США была не только фронтом, но и перестройкой общества.","effects":{"fame":3,"network":3,"risk":-1,"integrity":-2,"audience":3},"tags":["военная пресса"]},{"text":"Показать войну через связь фронта, заводов, семейных писем и неравной работы тыла.","verdict":"Широкий военный очерк","result":"Мини-рецензия: выбор делает войну объёмнее. Здесь героизм не отменяет усталость, а национальное единство не скрывает социальных различий. Такой материал лучше выдерживает проверку временем.","effects":{"craft":5,"integrity":4,"audience":4,"risk":2,"trauma":2},"tags":["Вторая мировая война","тыл"]},{"text":"Писать сатиру на военные лозунги сразу, без знания фронтового опыта.","verdict":"Ранний цинизм","result":"Мини-рецензия: скепсис может быть нужен, но без наблюдения он звучит как поза. Сатира сильна тогда, когда знает предмет точнее официального плаката.","effects":{"fame":1,"risk":4,"integrity":1,"craft":-2,"network":-3},"tags":["сатира"]}]},{"year":"1942","title":"Лагерь за колючей проволокой","scene":"Тебе становится известно о принудительном переселении японских американцев с Западного побережья. Среди них есть граждане США, студенты, фермеры, владельцы лавок. Редактор осторожничает: во время войны публика не хочет слышать, что государство может ошибаться.","fact":"В 1942 году после указа президента Франклина Рузвельта более ста тысяч людей японского происхождения, включая граждан США, были отправлены в лагеря интернирования.","choices":[{"text":"Поддержать официальную версию о необходимости мер безопасности.","verdict":"Официальная защита","result":"Мини-рецензия: решение снижает риск, но повторяет язык власти без проверки человеческой цены. Для автора это слабое место: страх войны подменяет вопрос о правах граждан.","effects":{"network":4,"money":2,"risk":-3,"integrity":-5,"craft":-2},"tags":["официальная позиция"]},{"text":"Собрать истории семей, потерянных домов, школ, ферм и попыток сохранить достоинство.","verdict":"Свидетельство о несправедливости","result":"Мини-рецензия: выбор трудный, но важный. Текст не отменяет военную тревогу, а показывает, что безопасность без правовой меры может разрушать жизни собственных граждан.","effects":{"craft":5,"integrity":6,"risk":4,"audience":2,"trauma":2},"tags":["интернирование","гражданские права"]},{"text":"Упомянуть лагеря одной фразой в романе о Калифорнии.","verdict":"Слишком осторожно","result":"Мини-рецензия: намёк лучше молчания, но тема требует большего пространства. Когда за событием стоят тысячи семей, случайная деталь выглядит уклонением.","effects":{"integrity":1,"craft":1,"risk":-1,"audience":0},"tags":["намёк"]}]},{"year":"1945","title":"Возвращение солдата","scene":"Война закончилась. Солдаты возвращаются домой, но дома их ждут не только парады: травма, инвалидность, молчание, расовое неравенство, поиск работы. Издатель просит роман о победе и новой спокойной жизни, но герои не умеют просто вернуться назад.","fact":"После Второй мировой войны американская литература и кино часто обращались к теме возвращения ветеранов, травмы, семейного разрыва и нового потребительского общества.","choices":[{"text":"Написать ясный роман о том, как победа всё исправила.","verdict":"Утешительная версия","result":"Мини-рецензия: такой текст может поддержать настроение времени, но он слишком быстро закрывает последствия войны. Возвращение не равно исцелению, и читатель это почувствует.","effects":{"fame":2,"audience":4,"money":3,"integrity":-3,"craft":-1,"trauma":-1},"tags":["послевоенный оптимизм"]},{"text":"Показать ветерана, который молчит за семейным столом и не узнаёт прежнюю жизнь.","verdict":"Тихая травма","result":"Мини-рецензия: сильный выбор. В нём нет лишнего пафоса, зато есть точная сцена: человек формально вернулся, но внутренне ещё не дома. Такая тема хорошо раскрывает послевоенную Америку.","effects":{"craft":5,"integrity":5,"trauma":4,"audience":3},"tags":["послевоенная травма"]},{"text":"Сделать героя циничным детективом, который решает чужие дела, но избегает собственной памяти.","verdict":"Жанровая маска","result":"Мини-рецензия: жанр может быть удачным способом говорить о травме косвенно. Если не забыть внутренний конфликт, детективная форма даст тексту скорость и тёмный послевоенный воздух.","effects":{"fame":3,"craft":3,"audience":4,"integrity":1,"risk":1},"tags":["нуар","жанровая проза"]}]},{"year":"1947","title":"Повестка из комитета","scene":"В Голливуде и издательствах начинают проверять политические связи. Друзей вызывают на слушания, сценаристы теряют работу, имена исчезают из титров. Тебя просят подписать заявление, осуждающее коллег, чтобы сохранить контракт.","fact":"В конце 1940-х и 1950-е годы антикоммунистические расследования и чёрные списки серьёзно повлияли на американскую культуру, кино, театр и литературу.","choices":[{"text":"Подписать заявление и публично отмежеваться от коллег.","verdict":"Карьера ценой доверия","result":"Мини-рецензия: выбор спасает контракт, но оставляет тяжёлый след. В культурной памяти такие решения часто читаются не как осторожность, а как участие в давлении на других.","effects":{"money":5,"network":4,"risk":-4,"integrity":-6,"fame":1},"tags":["чёрные списки","карьерный компромисс"]},{"text":"Отказаться подписывать и потерять часть работы.","verdict":"Репутационная стойкость","result":"Мини-рецензия: решение дорогое, но ясное. Оно не делает автора автоматически великим, зато сохраняет границу между страхом и доносом. Такая биография позже читается внимательнее.","effects":{"integrity":6,"risk":5,"money":-4,"network":-3,"craft":1},"tags":["антикоммунизм","гражданская позиция"]},{"text":"Уехать из Голливуда и писать под псевдонимом для малых изданий.","verdict":"Выживание в тени","result":"Мини-рецензия: это не героический жест, но реалистичная стратегия. Автор сохраняет работу с текстом, хотя публичное имя временно ослабевает.","effects":{"craft":3,"risk":2,"money":1,"fame":-2,"integrity":2},"tags":["псевдоним","периферия"]}]},{"year":"1951","title":"Дорога без плана","scene":"Ты едешь автостопом через Денвер, Сан-Франциско и маленькие станции. В барах звучит джаз, в блокноте появляются быстрые фразы, разговоры с незнакомцами и чувство усталости от послевоенной нормальности. Издатель говорит, что книга без привычного сюжета не удержит читателя.","fact":"Бит-поколение 1950-х годов связано с дорогой, джазовой импровизацией, критикой потребительской стабильности, интересом к Востоку и новым формам письма.","choices":[{"text":"Оставить текст рваным, быстрым, похожим на дорогу и импровизацию.","verdict":"Ритм поколения","result":"Мини-рецензия: выбор рискованный, но органичный. Если книга говорит о движении и поиске свободы, слишком гладкая форма ей повредит. Неровность здесь может стать стилем.","effects":{"fame":4,"craft":4,"integrity":4,"risk":3,"audience":4},"tags":["бит-поколение","дорога"]},{"text":"Переписать всё как классический роман взросления с понятным финалом.","verdict":"Прирученная дорога","result":"Мини-рецензия: текст станет легче продавать, но потеряет нерв путешествия. Дорога в бит-культуре важна не как маршрут из точки А в точку Б, а как способ жить вне готового сценария.","effects":{"money":4,"audience":3,"network":2,"integrity":-3,"craft":-1},"tags":["классическая форма"]},{"text":"Убрать из книги джаз, разговорную речь и спорные сцены.","verdict":"Потеря голоса","result":"Мини-рецензия: решение делает текст безопаснее, но лишает его среды. Без музыки, устной речи и ночных разговоров остаётся только схема путешествия.","effects":{"risk":-2,"money":2,"integrity":-4,"craft":-3,"audience":-1},"tags":["самоцензура"]}]},{"year":"1954","title":"Школа после решения суда","scene":"Верховный суд признаёт расовую сегрегацию в государственных школах неконституционной. В южном городе родители спорят у школьных ворот, местная газета выбирает осторожные слова, а ученики оказываются в центре взрослого конфликта. Тебе предлагают написать рассказ от лица учителя.","fact":"Решение Brown v. Board of Education 1954 года стало важнейшим юридическим шагом против школьной сегрегации, хотя реальная десегрегация проходила тяжело и с сопротивлением.","choices":[{"text":"Показать конфликт глазами ребёнка, который впервые понимает устройство неравенства.","verdict":"Точный угол зрения","result":"Мини-рецензия: детская перспектива делает тему не проще, а острее. Через школьный коридор видно, как большой закон входит в частную жизнь, страх и взросление.","effects":{"craft":5,"integrity":5,"risk":3,"audience":3,"trauma":2},"tags":["десегрегация","детская перспектива"]},{"text":"Сделать рассказ нейтральным: все стороны просто не поняли друг друга.","verdict":"Ложное равновесие","result":"Мини-рецензия: спокойный тон не всегда означает точность. Когда речь идёт о лишении прав, нейтральность может скрывать, кто именно был лишён доступа к школе и безопасности.","effects":{"risk":-2,"network":2,"integrity":-4,"craft":-1,"audience":1},"tags":["ложная нейтральность"]},{"text":"Написать резкий обвинительный текст без персонажей, только с тезисами.","verdict":"Плакат вместо рассказа","result":"Мини-рецензия: позиция ясна, но художественная сила слабее. Тема заслуживает не только правильного вывода, но и живых людей, через которых читатель увидит цену сегрегации.","effects":{"integrity":3,"risk":3,"craft":-2,"audience":-1,"fame":1},"tags":["публицистика"]}]},{"year":"1955","title":"Автобус и бойкот","scene":"После ареста Розы Паркс в Монтгомери начинается бойкот городских автобусов. В церквях проходят собрания, люди ходят пешком на работу, водители такси помогают за сниженный тариф. Тебя просят написать материал быстро, пока событие ещё не стало историей.","fact":"Бойкот автобусов в Монтгомери 1955-1956 годов стал одним из ключевых эпизодов движения за гражданские права и вывел Мартина Лютера Кинга-младшего в общенациональную публичность.","choices":[{"text":"Сделать материал только о харизматичном лидере, почти без участников бойкота.","verdict":"Слишком узкий фокус","result":"Мини-рецензия: лидер важен, но движение держится на тысячах ежедневных решений. Если убрать женщин, прихожан, водителей и рабочих, история станет проще, чем была.","effects":{"fame":3,"audience":3,"integrity":-2,"craft":-1},"tags":["герой в центре"]},{"text":"Показать бойкот как коллективную дисциплину: собрания, маршруты пешком, страх и взаимопомощь.","verdict":"История движения","result":"Мини-рецензия: сильный выбор. Он показывает гражданские права не как один красивый жест, а как долгую работу общины. Такой текст точнее передаёт масштаб сопротивления.","effects":{"craft":5,"integrity":5,"risk":3,"audience":4,"network":1},"tags":["гражданские права","община"]},{"text":"Убрать имена и место, превратив событие в абстрактную притчу.","verdict":"Слишком общее","result":"Мини-рецензия: притча может быть выразительной, но здесь важны конкретные город, транспорт, закон и люди. Без фактуры событие теряет историческую силу.","effects":{"craft":1,"integrity":-1,"risk":-1,"audience":0},"tags":["абстракция"]}]},{"year":"1957","title":"Дом в пригороде","scene":"После войны растут пригороды, телевизоры входят в гостиные, реклама обещает удобную жизнь, автомобиль становится частью повседневности. Тебе предлагают роман о счастливой семье в новом доме. Но герой чувствует, что за аккуратной лужайкой прячутся скука, одиночество и страх быть «не таким».","fact":"Послевоенная массовая культура США связана с ростом пригородов, потребительского общества, телевидения и критикой стандартизированной благополучной жизни.","choices":[{"text":"Написать пригород как идеал без трещин и сомнений.","verdict":"Рекламная открытка","result":"Мини-рецензия: такая история совпадает с мечтой телевидения и рекламы, но не задаёт вопросов. Она может быть приятной, однако почти не объясняет тревогу послевоенного среднего класса.","effects":{"money":4,"audience":4,"network":2,"integrity":-3,"craft":-1},"tags":["пригород","реклама"]},{"text":"Показать дом как место внешнего порядка и внутренней пустоты.","verdict":"Критика благополучия","result":"Мини-рецензия: выбор точный: ты не отрицаешь комфорт, а показываешь его цену. В такой прозе кухня, телевизор и газон становятся признаками времени, а не просто декором.","effects":{"craft":5,"integrity":4,"fame":2,"audience":3,"risk":1},"tags":["потребительская культура","одиночество"]},{"text":"Сделать героя бунтарём без причины, который просто презирает всех вокруг.","verdict":"Поза вместо анализа","result":"Мини-рецензия: раздражение героя может быть выразительным, но ему нужна причина. Без социальной и психологической основы протест выглядит подростковой маской.","effects":{"fame":1,"risk":2,"craft":-2,"integrity":-1,"audience":1},"tags":["пустой бунт"]}]},{"year":"1960","title":"Новая журналистика","scene":"Редактор просит большой материал о молодёжной культуре, телевидении и политике. Ты видишь, что сухая газетная заметка не передаёт скорость времени: кампусы спорят, музыка меняется, реклама говорит ярче чиновников. Появляется соблазн писать репортаж как сцену романа.","fact":"В 1960-е годы новая журналистика активно использовала литературные приёмы в репортаже: сцену, диалог, авторское присутствие и внимание к деталям среды.","choices":[{"text":"Оставить материал максимально сухим: даты, фамилии, официальные комментарии.","verdict":"Надёжно, но плоско","result":"Мини-рецензия: факты важны, но эпоха требует не только перечня. Без сцены и голоса текст не передаёт, как именно менялась повседневность.","effects":{"integrity":1,"risk":-1,"craft":-1,"audience":-1,"network":1},"tags":["традиционная заметка"]},{"text":"Написать репортаж сценами, но проверять каждую деталь и не выдумывать диалоги.","verdict":"Литературная точность","result":"Мини-рецензия: это лучший баланс формы и ответственности. Текст получает энергию романа, но остаётся журналистикой: читатель видит событие, а не авторскую фантазию вместо фактов.","effects":{"craft":5,"integrity":5,"fame":3,"audience":4,"risk":2},"tags":["новая журналистика","репортаж"]},{"text":"Смешать факты и вымышленные сцены ради сильного эффекта.","verdict":"Опасная эффектность","result":"Мини-рецензия: результат может быть ярким, но доверие ломается быстро. В документальном письме выдумка без предупреждения делает сильный стиль слабым доказательством.","effects":{"fame":3,"audience":3,"craft":1,"integrity":-5,"risk":3},"tags":["нарушение доверия"]}]},{"year":"1963","title":"Марш и речь","scene":"В Вашингтоне собираются сотни тысяч людей, звучат речи о работе, свободе и равных правах. Газета просит короткую колонку к утру. Можно написать красивую фразу о надежде, но за событием стоят годы арестов, бойкотов, насилия и организаторской работы.","fact":"Марш на Вашингтон 1963 года стал одним из самых известных событий движения за гражданские права; в нём соединились требования расового равенства, труда и политического представительства.","choices":[{"text":"Сфокусироваться только на знаменитой речи, не показывая социальные требования марша.","verdict":"Икона без контекста","result":"Мини-рецензия: речь действительно важна, но без требований работы, защиты и равного доступа событие превращается в красивую цитату. История сильнее, когда видны и слова, и организация за ними.","effects":{"fame":3,"audience":4,"integrity":-2,"craft":0},"tags":["известная речь"]},{"text":"Показать марш через участников: профсоюзы, студентов, священников, семьи, ветеранов борьбы.","verdict":"Полная картина","result":"Мини-рецензия: выбор расширяет событие. Марш становится не сценой для одного голоса, а собранием разных людей, которые требуют конкретных изменений. Это честнее и содержательнее.","effects":{"craft":5,"integrity":5,"audience":4,"risk":2},"tags":["Марш на Вашингтон","гражданские права"]},{"text":"Написать, что проблема почти решена, потому что марш прошёл мирно.","verdict":"Преждевременный финал","result":"Мини-рецензия: мирный марш не означает конца неравенства. Такой вывод успокаивает читателя, но плохо объясняет, почему борьба продолжалась после 1963 года.","effects":{"network":2,"risk":-1,"integrity":-4,"craft":-2,"audience":1},"tags":["упрощение"]}]},{"year":"1965","title":"Вьетнам в письмах домой","scene":"Молодой солдат присылает письма из Вьетнама. Дома его семья смотрит телевизионные новости и не понимает, почему официальные слова расходятся с тревогой в письмах. Тебе предлагают роман о войне, но издатель боится открытой критики.","fact":"Война во Вьетнаме стала одной из главных тем американской литературы, журналистики, кино и политической культуры второй половины XX века.","choices":[{"text":"Написать роман через письма солдата, теленовости и разговоры семьи дома.","verdict":"Разорванный опыт","result":"Мини-рецензия: выбор удачный: война показана не только на поле боя, но и в гостиной, где телевизор спорит с личным письмом. Так появляется ощущение расколотой страны.","effects":{"craft":5,"integrity":5,"trauma":4,"risk":3,"audience":3},"tags":["Вьетнам","письма"]},{"text":"Сделать войну приключением, где герой всегда уверен в правоте миссии.","verdict":"Упрощённый героизм","result":"Мини-рецензия: такой сюжет легко читается, но плохо соответствует культурному конфликту эпохи. Вьетнамская тема требует сомнения, травмы и вопроса о цене приказа.","effects":{"money":3,"audience":3,"risk":-1,"integrity":-4,"craft":-2},"tags":["военный боевик"]},{"text":"Писать только антивоенные лозунги, почти без персонажей.","verdict":"Плакатный протест","result":"Мини-рецензия: позиция ясна, но литература сильнее, когда показывает людей внутри истории. Без конкретных судеб текст становится речью, а не романом.","effects":{"integrity":3,"risk":3,"craft":-2,"audience":-1},"tags":["антивоенный протест"]}]},{"year":"1968","title":"Год перелома","scene":"Новости приходят одна за другой: убийства Мартина Лютера Кинга и Роберта Кеннеди, протесты, беспорядки, съезд Демократической партии в Чикаго, война во Вьетнаме. Редакция просит немедленный текст, но любой простой ответ выглядит нечестным.","fact":"1968 год стал для США символом политического кризиса, общественного раскола, протестной культуры и недоверия к официальным институтам.","choices":[{"text":"Написать один большой текст о стране, которая спорит сама с собой.","verdict":"Сложный монтаж","result":"Мини-рецензия: выбор сильный, если выдержать форму. В одном году действительно сталкиваются война, расовая боль, молодёжный протест и кризис доверия. Монтаж разных сцен передаёт это лучше, чем один тезис.","effects":{"craft":6,"integrity":5,"risk":4,"audience":3,"trauma":3},"tags":["1968","общественный кризис"]},{"text":"Выбрать одну удобную сторону и объяснить всё чужой провокацией.","verdict":"Слишком простое объяснение","result":"Мини-рецензия: такая версия может понравиться части аудитории, но не выдерживает сложности года. Когда конфликт глубокий, поиск одного виновника обычно обедняет текст.","effects":{"fame":2,"audience":3,"integrity":-4,"craft":-2,"risk":1},"tags":["упрощение конфликта"]},{"text":"Замолчать на год и вернуться к частной прозе без политики.","verdict":"Пауза с ценой","result":"Мини-рецензия: молчание может быть способом выжить, но 1968 год слишком заметен, чтобы исчезнуть из биографии автора. Позже такая пауза будет читаться как выбор, а не как пустое место.","effects":{"risk":-2,"trauma":-1,"integrity":-2,"craft":1,"fame":-1},"tags":["уход в частную тему"]}]},{"year":"1969","title":"Новые публичные голоса","scene":"После городских протестов и культурных перемен издатель ищет тексты о людях, которых раньше редко пускали в центр американского канона. В редакции спорят о языке: можно ли писать о сексуальности, расе, бедности и теле прямо, без привычных прикрытий.","fact":"Конец 1960-х связан с ростом контркультуры, движений за гражданские права, феминистской повестки, борьбы ЛГБТ-сообщества за видимость и пересмотром культурного канона.","choices":[{"text":"Оставить центр прежним: писать только о героях, уже привычных издательскому рынку.","verdict":"Сохранение старой рамки","result":"Мини-рецензия: решение снижает риск, но не чувствует сдвиг эпохи. Американская литература второй половины века расширялась именно за счёт новых голосов и тем.","effects":{"money":3,"network":2,"risk":-2,"integrity":-3,"craft":-1},"tags":["старый канон"]},{"text":"Дать место героям с разным происхождением, языком, опытом тела и публичной уязвимостью.","verdict":"Расширение канона","result":"Мини-рецензия: выбор помогает тексту увидеть Америку шире. Важно не использовать новых героев как украшение, а дать им собственную речь, конфликт и право на сложность.","effects":{"craft":5,"integrity":5,"audience":4,"risk":3},"tags":["новые голоса","контркультура"]},{"text":"Сделать скандальность главной целью и заменить характеры провокациями.","verdict":"Провокация без глубины","result":"Мини-рецензия: смелая тема не спасает слабую работу. Если персонажи существуют только ради шока, текст быстро устаревает и не даёт настоящего разговора.","effects":{"fame":4,"audience":3,"risk":4,"craft":-3,"integrity":-2},"tags":["скандальность"]}]},{"year":"1972","title":"Женский голос в издательстве","scene":"Редактор просит роман о семье, но предлагает оставить карьерные желания героини второстепенными: «читателю важнее любовь». В то же время в университетах, журналах и книжных клубах обсуждают женский труд, брак, образование, тело и право говорить от первого лица.","fact":"Вторая волна феминизма в США повлияла на литературу, журналистику, издательский рынок и академическое изучение женского письма.","choices":[{"text":"Согласиться и оставить героиню только в роли жены и матери.","verdict":"Привычная схема","result":"Мини-рецензия: такой сюжет может быть эмоциональным, но он отказывается от главного вопроса эпохи: что происходит, когда женщина хочет не только поддерживать чужую жизнь, но и строить свою.","effects":{"money":3,"audience":3,"integrity":-3,"craft":-1},"tags":["семейная схема"]},{"text":"Написать героиню через работу, брак, усталость, желание образования и конфликт с ожиданиями семьи.","verdict":"Живая сложность","result":"Мини-рецензия: выбор делает персонажа объёмным. Феминистская тема здесь не лозунг, а ежедневный опыт времени, денег, дома, профессии и права на собственный голос.","effects":{"craft":5,"integrity":5,"audience":4,"risk":2},"tags":["феминизм","женское письмо"]},{"text":"Превратить всех мужчин в карикатурных противников героини.","verdict":"Схема наоборот","result":"Мини-рецензия: злость понятна, но карикатура упрощает конфликт. Сильнее работает текст, где система ожиданий видна даже в близких людях, а не только в очевидных врагах.","effects":{"integrity":1,"risk":2,"craft":-2,"audience":1},"tags":["карикатура"]}]},{"year":"1973","title":"Голос коренных народов","scene":"Ты едешь на Запад писать о резервации, музеях и протестах коренных народов. Туристический журнал хочет материал о красивых орнаментах и древних легендах, но собеседники говорят о земле, школах-интернатах, языке, праве на самоуправление и современном искусстве.","fact":"Во второй половине XX века усилились движения коренных народов США за права, культурное признание, суверенитет и возвращение собственной истории в публичное пространство.","choices":[{"text":"Сделать красивый этнографический очерк без современной политики.","verdict":"Туристический взгляд","result":"Мини-рецензия: текст может быть визуально ярким, но он оставляет живых людей в прошлом. Коренные культуры XX века — это не только музей и орнамент, но и борьба за язык, землю и современное искусство.","effects":{"money":3,"audience":3,"integrity":-5,"craft":-1},"tags":["туристический текст"]},{"text":"Строить материал на интервью, истории семьи, языке, земле и современном активизме.","verdict":"Уважительное свидетельство","result":"Мини-рецензия: выбор требует аккуратности и проверки, зато возвращает теме настоящее время. Такой текст не говорит за людей, а даёт им пространство говорить самим.","effects":{"craft":5,"integrity":6,"risk":3,"audience":3},"tags":["коренные народы","суверенитет"]},{"text":"Использовать образы коренных народов как мистический фон для приключенческого романа.","verdict":"Экзотизация","result":"Мини-рецензия: это самый слабый путь. Он берёт культурные символы, но не интересуется людьми, которым они принадлежат. В итоге получается не уважение, а декоративное использование чужой истории.","effects":{"fame":2,"money":2,"integrity":-6,"craft":-3,"risk":2},"tags":["экзотизация"]}]},{"year":"1977","title":"Семейная память и телевидение","scene":"После успеха больших исторических сериалов издатель предлагает книгу о нескольких поколениях семьи. В обществе растёт интерес к родословной, рабству, миграции и тому, как частная память связана с национальной историей. Перед тобой выбор: сделать семейную хронику удобной или болезненно точной.","fact":"В 1970-е годы широкая публика активно обращалась к темам семейной истории, рабства, расовой памяти и связи личной биографии с историей страны.","choices":[{"text":"Написать семейную хронику через документы, рассказы старших, пробелы памяти и спорные места.","verdict":"Ответственная память","result":"Мини-рецензия: выбор сильный, потому что не притворяется, будто прошлое лежит готовым и ясным. Семейная история становится поиском, где важны и найденные факты, и молчание архива.","effects":{"craft":5,"integrity":5,"audience":5,"trauma":2},"tags":["семейная память","архив"]},{"text":"Сделать прошлое полностью героическим, без насилия и противоречий.","verdict":"Сглаженная хроника","result":"Мини-рецензия: такой текст легче читать, но он плохо работает с историей. Память становится украшением, если из неё убрать боль, неравенство и цену выживания.","effects":{"audience":3,"money":3,"integrity":-4,"craft":-2},"tags":["сглаженная история"]},{"text":"Построить книгу только на шокирующих эпизодах, почти без семейной повседневности.","verdict":"Травма без жизни","result":"Мини-рецензия: тяжёлые факты важны, но семья не состоит только из катастроф. Без быта, языка, еды, работы и привязанности прошлое выглядит как набор ударов, а не человеческая история.","effects":{"fame":3,"risk":3,"trauma":4,"craft":-1,"integrity":0},"tags":["травматическая история"]}]},{"year":"1981","title":"Новая болезнь и молчание","scene":"В больших городах врачи и активисты говорят о новой смертельной болезни, но многие редакции избегают темы: слишком много стигмы, страха и предрассудков. Тебе предлагают материал о друзьях, больницах, утрате и борьбе за внимание общества.","fact":"AIDS-кризис 1980-х годов стал тяжёлой темой американской культуры, связанной с медициной, стигмой, ЛГБТ-сообществом, активизмом и памятью о потерях.","choices":[{"text":"Писать осторожно и без имён, чтобы никого не раздражать.","verdict":"Осторожность на грани молчания","result":"Мини-рецензия: забота о людях важна, но слишком общий текст может поддержать невидимость проблемы. В кризисе молчание тоже становится позицией.","effects":{"risk":-2,"network":1,"integrity":-2,"craft":0,"audience":-1},"tags":["осторожность"]},{"text":"Показать болезнь через конкретных людей, заботу, страх, активизм и язык стигмы.","verdict":"Свидетельство с достоинством","result":"Мини-рецензия: выбор точный и этически сильный. Он не превращает болезнь в сенсацию, а показывает, как общественный страх влияет на тело, дружбу, больницу и память.","effects":{"craft":5,"integrity":6,"risk":4,"trauma":5,"audience":3},"tags":["AIDS-кризис","активизм"]},{"text":"Сделать материал пугающей сенсацией с акцентом на слухах.","verdict":"Вредная сенсация","result":"Мини-рецензия: это может собрать внимание, но разрушает доверие и усиливает стигму. Тема требует фактов и уважения, а не страха как приёма.","effects":{"fame":4,"audience":3,"integrity":-6,"craft":-3,"risk":3},"tags":["стигма","сенсационность"]}]},{"year":"1986","title":"Граница и новый язык","scene":"На Юго-Западе растёт внимание к мексикано-американскому опыту: двуязычные семьи, работа на полях и в городах, школы, документы, граница, музыка и память о земле. Издатель просит сделать текст «более универсальным» и убрать испанские слова.","fact":"Чикано-литература и мексикано-американская культура во второй половине XX века стали важной частью разговоров о языке, гражданских правах, труде, границе и идентичности США.","choices":[{"text":"Сохранить двуязычные фразы и объяснять смысл через ситуацию, а не через сноски в каждом предложении.","verdict":"Живой язык","result":"Мини-рецензия: выбор уважает среду героя. Двуязычие здесь не украшение, а часть мышления, семьи и места. Такой текст может требовать большего внимания, но становится честнее.","effects":{"craft":5,"integrity":5,"audience":3,"risk":2},"tags":["чикано-культура","двуязычие"]},{"text":"Убрать испанские слова и сделать героев максимально нейтральными.","verdict":"Сглаженная универсальность","result":"Мини-рецензия: текст станет проще для части рынка, но потеряет голос региона. Универсальность не обязана означать стирание языка и происхождения.","effects":{"money":3,"network":2,"risk":-1,"integrity":-4,"craft":-2},"tags":["стирание языка"]},{"text":"Сделать границу только местом криминального сюжета.","verdict":"Узкий штамп","result":"Мини-рецензия: криминальный конфликт возможен, но если граница сводится только к опасности, исчезают семья, труд, музыка, образование и память. Это бедная версия сложной культуры.","effects":{"fame":2,"audience":3,"integrity":-3,"craft":-2,"risk":1},"tags":["стереотип"]}]},{"year":"1992","title":"Город после взрыва","scene":"Лос-Анджелес переживает массовые беспорядки после оправдания полицейских, избивших Родни Кинга. В одном городе сталкиваются расовое напряжение, полиция, бедность, корейско-американские магазины, телевидение и усталость районов, которые давно не слышали. Тебе нужно написать текст без простых виновников.","fact":"События в Лос-Анджелесе 1992 года стали символом расового, социального и городского напряжения конца XX века в США.","choices":[{"text":"Выбрать одного виновника и объяснить все события только им.","verdict":"Удобное сокращение","result":"Мини-рецензия: такой текст даёт быстрый вывод, но не объясняет город. В 1992 году важны полиция, бедность, медиа, расовые отношения, бизнес и накопленная несправедливость одновременно.","effects":{"fame":2,"audience":3,"integrity":-4,"craft":-2},"tags":["простое обвинение"]},{"text":"Построить текст из нескольких районов и голосов: жителей, владельцев лавок, подростков, репортёров, юристов.","verdict":"Многоголосый город","result":"Мини-рецензия: выбор сложный, но честный. Он не оправдывает насилие, а показывает, почему город оказался настолько хрупким. Такая структура подходит для конца XX века с его медиа и конфликтами идентичности.","effects":{"craft":6,"integrity":5,"risk":3,"audience":4,"trauma":3},"tags":["Лос-Анджелес","многоэтничный город"]},{"text":"Сделать текст только о телевизионной картинке и забыть людей за кадром.","verdict":"Экран без города","result":"Мини-рецензия: телевидение важно, но экран не заменяет район. Если остаться только на уровне кадра, причины конфликта исчезают за зрелищем.","effects":{"fame":3,"audience":2,"integrity":-3,"craft":-1},"tags":["медиа-событие"]}]},{"year":"1999","title":"Архив перед новым веком","scene":"Ты разбираешь коробки с рукописями, письмами, фотографиями, газетными вырезками и черновиками. Университет предлагает передать архив в библиотеку, но агент хочет продать только самые громкие документы. От решения зависит, как будущие читатели увидят твою эпоху.","fact":"К концу XX века архивы, университетские коллекции, переиздания и культурная критика активно пересматривали американский литературный канон и возвращали забытые голоса.","choices":[{"text":"Передать архив целиком: черновики, письма, спорные материалы и рабочие заметки.","verdict":"Полная память","result":"Мини-рецензия: выбор уважает будущего читателя. Архив показывает не только готовые книги, но и путь мысли, сомнения, ошибки и связи автора с эпохой.","effects":{"integrity":6,"craft":2,"fame":3,"audience":3,"money":-1},"tags":["архив","канон"]},{"text":"Оставить только удачные документы и скрыть всё неудобное.","verdict":"Отполированная биография","result":"Мини-рецензия: такой архив выглядит аккуратно, но слишком управляемо. Будущая критика всё равно будет искать пробелы, а отсутствие сложных материалов станет частью истории.","effects":{"fame":2,"money":2,"integrity":-4,"craft":0},"tags":["контроль образа"]},{"text":"Продать самые сенсационные письма отдельно, не заботясь о контексте.","verdict":"Рынок вместо памяти","result":"Мини-рецензия: решение приносит деньги, но дробит наследие. Документ без контекста легко превращается в скандал, а не в понимание автора и века.","effects":{"money":5,"fame":2,"integrity":-5,"audience":1},"tags":["сенсационный архив"]}]}];const labels={fame:'известность',money:'деньги',craft:'мастерство',integrity:'честность',network:'связи',risk:'риск',trauma:'травма',audience:'аудитория'},order=['fame','money','craft','integrity','network','risk','trauma','audience'];let state={profile:null,stats:null,step:0,badges:[],log:[]};const $=id=>document.getElementById(id),clamp=v=>Math.max(0,Math.min(100,v));function init(){$('profiles').innerHTML=profiles.map(p=>`<button class="profile" data-id="${p.id}"><div class="avatar"></div><strong>${p.name}</strong><span>${p.route}</span><p>Культурный код: ${p.tags.join(', ')}</p></button>`).join('');document.querySelectorAll('.profile').forEach(b=>b.onclick=()=>start(b.dataset.id));$('reset').onclick=()=>start(state.profile.id)}function start(id){const p=profiles.find(x=>x.id===id)||profiles[0];state={profile:p,stats:{...p.stats},step:0,badges:[...p.tags],log:[]};$('writerStart').style.display='none';$('writerEnding').style.display='none';$('writerGame').style.display='grid';$('pname').textContent=p.name;$('proute').textContent=p.route;render()}function renderStats(){$('stats').innerHTML=order.map(k=>`<div class="stat"><span>${labels[k]}</span><div class="bar"><i style="width:${clamp(state.stats[k]||0)}%"></i></div><b>${state.stats[k]||0}</b></div>`).join('');$('badges').innerHTML=[...new Set(state.badges)].slice(-28).map(x=>`<span class="badge">${x}</span>`).join('')}function render(){if(state.step>=episodes.length)return finish();const e=episodes[state.step];renderStats();$('stepLabel').textContent=`${state.step+1} / ${episodes.length}`;$('yearLabel').textContent=e.year;$('prog').style.width=(state.step/episodes.length*100)+'%';$('year').textContent=e.year;$('title').textContent=e.title;$('scene').textContent=e.scene;$('fact').innerHTML='<b>Историческая опора:</b> '+e.fact;$('result').style.display='none';$('choices').innerHTML=e.choices.map((c,i)=>`<button class="choice" data-i="${i}"><b>${c.text}</b><small>выбор ${i+1}</small></button>`).join('');document.querySelectorAll('.choice').forEach(b=>b.onclick=()=>choose(+b.dataset.i));renderLog()}function choose(i){const e=episodes[state.step],c=e.choices[i];Object.entries(c.effects).forEach(([k,v])=>state.stats[k]=clamp((state.stats[k]||0)+v));c.tags.forEach(t=>state.badges.push(t));state.log.push({year:e.year,title:e.title,choice:c.text,verdict:c.verdict,result:c.result});document.querySelectorAll('.choice').forEach(b=>b.disabled=true);$('result').style.display='block';$('verdict').textContent=c.verdict;$('resText').textContent=c.result;$('delta').innerHTML=Object.entries(c.effects).map(([k,v])=>`<span class="${v>=0?'plus':'minus'}">${labels[k]} ${v>0?'+':''}${v}</span>`).join('')+c.tags.map(t=>`<span class="plus">статус: ${t}</span>`).join('');$('writerNext').onclick=()=>{state.step++;render()};renderStats();renderLog()}function renderLog(){if(!state.log.length){$('log').innerHTML='<div class="entry"><b>Архив пуст</b><p>Сделайте первый выбор.</p></div>';return}$('log').innerHTML=state.log.slice().reverse().map(x=>`<div class="entry"><b>${x.year} · ${x.title}</b><p><b>${x.verdict}</b></p><p>${x.choice}</p></div>`).join('')}function finish(){$('writerGame').style.display='none';$('writerEnding').style.display='block';let s=state.stats,t='Заметный автор с неоднозначным наследием',d='Ты прошёл XX век без полного провала, но и без абсолютного прорыва: в биографии остались сильные книги, компромиссы и упущенные темы.';if(s.fame>=70&&s.integrity>=65&&s.craft>=65){t='Канонический автор сложной Америки';d='Ты стал известным не потому, что выбирал безопасный путь, а потому что удержал связь с реальными конфликтами века: миграцией, войной, расизмом, рынком, цензурой и новыми голосами.'}else if(s.fame>=75&&s.integrity<45){t='Медийный бренд с проблемной биографией';d='Ты добился известности и денег, но слишком часто выбирал рынок и власть. Поздняя критика читает тебя как талант, не всегда выдержавший давление эпохи.'}else if(s.integrity>=75&&s.fame<55){t='Автор, которого открыли заново';d='При жизни ты не всегда был массово известен, зато сохранил честность. Архивы и новые читатели возвращают твои книги в канон.'}else if(s.risk>=70&&s.money<35){t='Опасный автор на границе чёрного списка';d='Ты терял контракты и связи, но оставил тексты сопротивления. Позднее твоя биография выглядит как история гражданского мужества.'}else if(s.trauma>=65){t='Большой свидетель с выгоревшим ресурсом';d='Ты видел слишком много: войну, насилие, болезни, публичные травмы. Литература сильна, но биография показывает цену свидетельства.'}let top=order.slice().sort((a,b)=>(s[b]||0)-(s[a]||0)).slice(0,3).map(k=>labels[k]).join(', ');$('writerEnding').innerHTML=`<div class="eyebrow">итог истории</div><h2>${t}</h2><p>${d}</p><div class="endgrid"><div class="endbox"><h3>Профиль</h3><p><b>Сильные стороны:</b> ${top}.</p><p><b>Статусы:</b> ${[...new Set(state.badges)].slice(-22).join(', ')}.</p></div><div class="endbox"><h3>Что случилось</h3><p>Твои решения сформировали литературную судьбу: известность ${s.fame}, честность ${s.integrity}, мастерство ${s.craft}, деньги ${s.money}, риск ${s.risk}, аудитория ${s.audience}.</p></div></div><div class="endbox" style="margin-top:12px"><h3>Хроника решений</h3>${state.log.map(x=>`<p><b>${x.year}</b> — ${x.verdict}: ${x.choice}</p>`).join('')}</div><button class="reset" onclick="location.reload()">пройти заново</button>`}init();

