(function(){
  const realPassportImages = {
      city: {url: 'https://commons.wikimedia.org/wiki/Special:FilePath/New%20York%20Sky-Line%20%281922%29.png?width=1400', note: 'Северо-Восток: Нью-Йорк, городская модерность 1920-х'},
      books: {url: 'https://commons.wikimedia.org/wiki/Special:FilePath/Main%20Reading%20Room%20of%20the%20New%20York%20City%20Public%20Library%20on%205th%20Avenue%20ca%2C%201910-1920.jpg?width=1400', note: 'Северо-Восток: библиотека, издательства, литературная среда'},
      media: {url: 'https://commons.wikimedia.org/wiki/Special:FilePath/Times%20Square%20Building%2C%201920%20%28MOHAI%206069%29.jpg?width=1400', note: 'Северо-Восток: Таймс-сквер и медийная культура 1920-х'},
      farm: {url: 'https://commons.wikimedia.org/wiki/Special:FilePath/Christmas%20dinner%20in%20home%20of%20Earl%20Pauley%2C%20near%20Smithland%2C%20Iowa%2C%208b30046.jpg?width=1400', note: 'Средний Запад: фермерская семья в Айове, 1936'},
      factory: {url: 'https://commons.wikimedia.org/wiki/Special:FilePath/Hudson%20Motor%20Car%20Company%2C%20Detroit%2C%20Mich.jpg?width=1400', note: 'Средний Запад: автомобильная промышленность Детройта'},
      typewriter: {url: 'https://commons.wikimedia.org/wiki/Special:FilePath/Orson%20Welles%27s%20typewriter%20%28NMAH%202021.0169.01%29.jpg?width=1400', note: 'Средний Запад: печатная машинка 1930–1940-х'},
      southpic: {url: 'https://commons.wikimedia.org/wiki/Special:FilePath/Mepkin%20Plantation%20House.jpg?width=1400', note: 'Юг: старый южный дом и культурная память'},
      blues: {url: 'https://commons.wikimedia.org/wiki/Special:FilePath/Charley%20Patton%20%281929%20photo%20portrait%29.jpg?width=1400', note: 'Юг: блюз и афроамериканская музыкальная традиция'},
      rights: {url: 'https://commons.wikimedia.org/wiki/Special:FilePath/Civil%20Rights%20March%20on%20Washington%2C%20D.C.%20%28Dr.%20Martin%20Luther%20King%2C%20Jr.%20and%20Mathew%20Ahmann%20in%20a%20crowd.%29%20-%20NARA%20-%20542015%20-%20Restoration.jpg?width=1400', note: 'Юг/США: движение за гражданские права, 1963'},
      road: {url: 'https://commons.wikimedia.org/wiki/Special:FilePath/Del%27s%20Restaurant%20%28NBY%20436846%29.jpg?width=1400', note: 'Запад: Route 66 и дорожная культура 1950-х'},
      hollywood: {url: 'https://commons.wikimedia.org/wiki/Special:FilePath/Hollywoodland%20Sign%201920s.jpg?width=1400', note: 'Запад: Голливуд 1920-х'},
      jazz: {url: 'https://commons.wikimedia.org/wiki/Special:FilePath/New%20Orleans%20Owls%201922.jpg?width=1400', note: 'Запад/контркультура: джаз как ритм литературы и перформанса'}
  };
  function escapeHtml(value){
    return String(value || '').replace(/[&<>"']/g, function(ch){
      return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch];
    });
  }
  function findPhotoKey(element){
    if(!element) return 'city';
    const classes = Array.from(element.classList || []);
    return classes.find(function(cls){ return realPassportImages[cls]; }) || 'city';
  }
  function bgFor(key){
    const data = realPassportImages[key] || realPassportImages.city;
    return 'linear-gradient(180deg, rgba(7,12,24,.03), rgba(7,12,24,.14) 45%, rgba(7,12,24,.58)), url("' + data.url + '")';
  }
  function applyHistoricalPhoto(element, key){
    if(!element) return;
    element.style.setProperty('background-image', bgFor(key), 'important');
    element.style.setProperty('background-size', 'cover', 'important');
    element.style.setProperty('background-position', 'center', 'important');
    element.setAttribute('data-photo-source', (realPassportImages[key] || realPassportImages.city).note);
  }
  function paintRealPassportPhotos(){
    const photos = document.getElementById('photos');
    if(photos){
      photos.querySelectorAll('.photo').forEach(function(card){
        const label = (card.querySelector('span') && card.querySelector('span').textContent.trim()) || card.textContent.trim();
        const key = findPhotoKey(card);
        card.innerHTML = '<span>' + escapeHtml(label) + '</span>';
        applyHistoricalPhoto(card, key);
      });
    }
    const passportPhoto = document.getElementById('passportPhoto');
    if(passportPhoto){
      const key = findPhotoKey(passportPhoto);
      passportPhoto.innerHTML = '<span>историческое фото региона</span>';
      applyHistoricalPhoto(passportPhoto, key);
    }
    const idPhoto = document.querySelector('.passport-id-photo');
    if(idPhoto){
      let key = 'city';
      try {
        if(typeof regions !== 'undefined' && typeof active !== 'undefined' && regions[active] && regions[active].photos && regions[active].photos[0]) {
          key = regions[active].photos[0][1];
        }
      } catch(e) {}
      idPhoto.innerHTML = '<span>историческое фото региона</span>';
      applyHistoricalPhoto(idPhoto, key);
    }
  }
  if(typeof renderPassport === 'function'){
    const previousRenderPassport = renderPassport;
    renderPassport = function(){
      previousRenderPassport.apply(this, arguments);
      paintRealPassportPhotos();
    };
    renderPassport();
  } else {
    document.addEventListener('DOMContentLoaded', paintRealPassportPhotos);
  }
})();

